// Part 107 question bank. Each: id, c=category, a=ACS code, q=question, o=options, k=correct answer, e=explanation, img, area=test area.
window.P107_BANK=[{"id": 1, "c": "Regulations", "a": "UA.I.B.K21", "q": "According to 14 CFR Part 107, what is the maximum groundspeed for a small UA?", "o": ["87 knots (100 mph)", "100 knots (115 mph)", "80 knots (90 mph)"], "k": "87 knots (100 mph)", "e": "Section 107.51 states the maximum groundspeed is 87 knots (100 miles per hour).", "img": null, "area": "regs"}, {"id": 2, "c": "Regulations", "a": "UA.I.A.K1", "q": "According to 14 CFR Part 48, when must a person register a small UA with the FAA?", "o": ["If it weighs more than 0.55 pounds and less than 55 pounds", "Only if it weighs more than 2 pounds", "Only if it has a camera"], "k": "If it weighs more than 0.55 pounds and less than 55 pounds", "e": "Part 48 requires registration for small UA over 0.55 pounds. Note: under Part 107, every drone flown commercially must be registered, no matter its weight.", "img": null, "area": "regs"}, {"id": 3, "c": "Regulations", "a": "UA.I.B.K8", "q": "How many hours must pass between consuming alcohol and operating a small UA?", "o": ["8 hours", "12 hours", "24 hours"], "k": "8 hours", "e": "14 CFR Part 107.27 prohibits operation within 8 hours of consuming alcohol ('Bottle to Throttle').", "img": null, "area": "regs"}, {"id": 4, "c": "Regulations", "a": "UA.I.B.K8", "q": "What is the blood alcohol concentration (BAC) limit for a remote pilot?", "o": ["0.04%", "0.08%", "0.00%"], "k": "0.04%", "e": "A remote pilot may not operate if they have a BAC of 0.04% or greater.", "img": null, "area": "regs"}, {"id": 5, "c": "Regulations", "a": "UA.I.B.K6", "q": "A small UA must be operated in a manner which does not endanger the life or property of another. This is known as:", "o": ["Careless or Reckless Operation", "Standard Operating Procedure", "Risk Management"], "k": "Careless or Reckless Operation", "e": "Section 107.23 prohibits careless or reckless operation.", "img": null, "area": "regs"}, {"id": 6, "c": "Regulations", "a": "UA.I.B.K9", "q": "To operate at night (after sunset), your drone must be equipped with:", "o": ["Anti-collision lights visible for 3 statute miles", "Navigation lights", "Infrared camera"], "k": "Anti-collision lights visible for 3 statute miles", "e": "Operations at night or civil twilight require anti-collision lights visible for at least 3 SM.", "img": null, "area": "regs"}, {"id": 7, "c": "Regulations", "a": "UA.I.A.K1", "q": "What is the minimum age to register a drone?", "o": ["13 years old", "16 years old", "18 years old"], "k": "13 years old", "e": "You must be 13 to register a drone. You must be 16 to take the Part 107 test.", "img": null, "area": "regs"}, {"id": 8, "c": "Regulations", "a": "UA.I.A.K2", "q": "How often must a remote pilot pass a recurrent knowledge test or training?", "o": ["Every 24 calendar months", "Every 12 months", "Every 5 years"], "k": "Every 24 calendar months", "e": "Recurrent training/testing is required every 24 calendar months to keep currency.", "img": null, "area": "regs"}, {"id": 9, "c": "Regulations", "a": "UA.I.B.K3", "q": "If you change your address, you must notify the FAA within:", "o": ["30 days", "10 days", "90 days"], "k": "30 days", "e": "Certificate holders must notify the FAA of an address change within 30 days.", "img": null, "area": "regs"}, {"id": 10, "c": "Regulations", "a": "UA.I.A.K1", "q": "The maximum weight of a small unmanned aircraft under Part 107 is:", "o": ["Less than 55 lbs", "55 lbs exactly", "25 kgs"], "k": "Less than 55 lbs", "e": "The aircraft must weigh less than 55 lbs (up to 54.99 lbs) at takeoff.", "img": null, "area": "regs"}, {"id": 11, "c": "Regulations", "a": "UA.I.B.K21", "q": "What is the minimum visibility required to fly a sUAS?", "o": ["3 Statute Miles", "1 Statute Mile", "5 Statute Miles"], "k": "3 Statute Miles", "e": "Part 107.51 requires at least 3 statute miles of visibility from the control station.", "img": null, "area": "regs"}, {"id": 12, "c": "Regulations", "a": "UA.I.B.K21", "q": "What is the minimum distance you must stay below clouds?", "o": ["500 feet", "1000 feet", "2000 feet"], "k": "500 feet", "e": "You must remain at least 500 feet below clouds.", "img": null, "area": "regs"}, {"id": 13, "c": "Regulations", "a": "UA.I.B.K21", "q": "What is the minimum horizontal distance you must stay from clouds?", "o": ["2000 feet", "500 feet", "1 mile"], "k": "2000 feet", "e": "You must remain at least 2000 feet horizontally from clouds.", "img": null, "area": "regs"}, {"id": 14, "c": "Regulations", "a": "UA.I.B.K22", "q": "Who is responsible for ensuring the sUAS is in safe operating condition?", "o": ["Remote Pilot in Command", "Owner", "Visual Observer"], "k": "Remote Pilot in Command", "e": "The Remote PIC is responsible for the preflight check and safe operation.", "img": null, "area": "regs"}, {"id": 16, "c": "Regulations", "a": "UA.I.B.K19", "q": "When can you fly over a person?", "o": ["If they are a direct participant or under a covered structure/vehicle", "If they sign a waiver", "Never"], "k": "If they are a direct participant or under a covered structure/vehicle", "e": "Part 107.39 restricts flight over human beings unless they are participants or protected.", "img": null, "area": "regs"}, {"id": 17, "c": "Regulations", "a": "UA.I.B.K19", "q": "Which Category of Operations Over People requires a 'Declaration of Compliance'?", "o": ["Category 2 and 3", "Category 1", "Category 4"], "k": "Category 2 and 3", "e": "Categories 2 and 3 require an FAA-accepted Declaration of Compliance from the manufacturer.", "img": null, "area": "regs"}, {"id": 18, "c": "Regulations", "a": "UA.I.B.K19", "q": "Category 1 operations over people allow drones weighing:", "o": ["0.55 lbs or less", "Up to 55 lbs", "Over 0.55 lbs"], "k": "0.55 lbs or less", "e": "Category 1 is for drones weighing 0.55 pounds or less with no exposed rotating parts that would cause injury.", "img": null, "area": "regs"}, {"id": 19, "c": "Regulations", "a": "UA.I.B.K23", "q": "What does Remote ID require?", "o": ["Broadcast of ID and location info", "A transponder", "ADS-B Out"], "k": "Broadcast of ID and location info", "e": "Remote ID requires the drone to broadcast identity, location, and control station location.", "img": null, "area": "regs"}, {"id": 20, "c": "Regulations", "a": "UA.I.B.K7", "q": "Can you carry hazardous material (HazMat) on a drone under Part 107?", "o": ["No", "Yes, with a waiver", "Yes, if < 1 lb"], "k": "No", "e": "Carriage of hazardous materials is prohibited under Part 107.", "img": null, "area": "regs"}, {"id": 21, "c": "Regulations", "a": "UA.I.B.K10", "q": "When a visual observer is used, who must be able to see the small UA?", "o": ["The VO, or the remote PIC and person manipulating the controls", "Only the remote PIC, at all times", "No one, if the FPV feed is clear"], "k": "The VO, or the remote PIC and person manipulating the controls", "e": "Section 107.31 lets the VO maintain VLOS; the remote PIC and person manipulating the controls must still be able to see it if needed.", "img": null, "area": "regs"}, {"id": 22, "c": "Regulations", "a": "UA.I.B.K5", "q": "When operating from a moving vehicle, you may:", "o": ["Only fly over sparsely populated areas", "Fly over cities", "Never fly"], "k": "Only fly over sparsely populated areas", "e": "Operation from a moving land vehicle is allowed only in sparsely populated areas.", "img": null, "area": "regs"}, {"id": 23, "c": "Regulations", "a": "UA.I.B.K5", "q": "Can you operate from a moving aircraft?", "o": ["No", "Yes", "With a waiver"], "k": "No", "e": "Part 107 prohibits operating a drone from a moving aircraft.", "img": null, "area": "regs"}, {"id": 24, "c": "Regulations", "a": "UA.I.B.K5", "q": "Are you allowed to transport property for compensation (delivery)?", "o": ["Yes, if total weight <55 lbs and within VLOS", "No", "Only in rural areas"], "k": "Yes, if total weight <55 lbs and within VLOS", "e": "Part 107 allows package delivery if within VLOS, not from a moving vehicle (unless sparse area), and <55lbs.", "img": null, "area": "regs"}, {"id": 25, "c": "Regulations", "a": "UA.I.C.K2", "q": "Conviction for growing marijuana results in:", "o": ["Denial of application for 1 year", "Lifetime ban", "No effect"], "k": "Denial of application for 1 year", "e": "A drug conviction results in a 1-year denial of application or suspension.", "img": null, "area": "regs"}, {"id": 26, "c": "Airspace", "a": "UA.I.B.K21", "q": "What is the maximum altitude allowed for sUAS operations (without a waiver)?", "o": ["400 feet AGL", "500 feet AGL", "1000 feet MSL"], "k": "400 feet AGL", "e": "You may not fly higher than 400 feet Above Ground Level (AGL), unless within 400 feet of a structure.", "img": null, "area": "air"}, {"id": 27, "c": "Airspace", "a": "UA.II.A.K1", "q": "What type of airspace requires ATC authorization before entering?", "o": ["Class B, C, D, and Surface E", "Class G", "Class E (at 700 ft)"], "k": "Class B, C, D, and Surface E", "e": "Controlled airspace (B, C, D, E Surface) requires prior authorization (usually via LAANC).", "img": null, "area": "air"}, {"id": 28, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class C airspace typically consists of:", "o": ["Surface area (5NM radius) and Shelf (10NM radius)", "A single 5NM circle", "An upside down wedding cake with 3 layers"], "k": "Surface area (5NM radius) and Shelf (10NM radius)", "e": "Class C usually has a surface area (5NM) and an outer shelf (10NM) extending from 1,200ft to 4,000ft.", "img": null, "area": "air"}, {"id": 29, "c": "Airspace", "a": "UA.II.A.K1", "q": "The 'floor' of Class E airspace indicated by a shaded magenta line is:", "o": ["700 feet AGL", "1200 feet AGL", "Surface"], "k": "700 feet AGL", "e": "Shaded Magenta = Class E starts at 700 ft AGL. (Shaded Blue = 1200 ft AGL).", "img": null, "area": "air"}, {"id": 31, "c": "Airspace", "a": "UA.II.A.K1", "q": "What does a dashed magenta line around an airport indicate?", "o": ["Class E Surface Area", "Class D Airspace", "Class G Airspace"], "k": "Class E Surface Area", "e": "Dashed Magenta indicates Class E airspace starting at the surface. Authorization is required.", "img": null, "area": "air"}, {"id": 32, "c": "Airspace", "a": "UA.II.A.K3", "q": "Restricted Areas (R-xxxx) denote:", "o": ["Unusual, often invisible hazards (artillery, missiles)", "Military training routes", "Parachute jump areas"], "k": "Unusual, often invisible hazards (artillery, missiles)", "e": "Restricted areas contain hazards like artillery firing. You need permission from the controlling agency to enter when active.", "img": null, "area": "air"}, {"id": 33, "c": "Airspace", "a": "UA.II.A.K3", "q": "Military Training Routes (MTRs) with 4 numbers (e.g., VR1234) are flown at:", "o": ["At or below 1500 ft AGL", "Above 1500 ft AGL", "Only above 10,000 ft"], "k": "At or below 1500 ft AGL", "e": "4 digits = Below 1500 AGL. 3 digits = Above 1500 AGL.", "img": null, "area": "air"}, {"id": 34, "c": "Airspace", "a": "UA.I.B.K21", "q": "You are flying near a tower marked '1000 (400)'. How high can you fly over it?", "o": ["800 feet AGL", "400 feet AGL", "You cannot fly over it"], "k": "800 feet AGL", "e": "Part 107 allows you to fly 400ft above a structure. If structure is 400ft tall, you can fly to 800ft AGL directly over it.", "img": null, "area": "air"}, {"id": 35, "c": "Airspace", "a": "UA.II.A.K1", "q": "What airspace is Class G?", "o": ["Uncontrolled", "Controlled", "Special Use"], "k": "Uncontrolled", "e": "Class G is uncontrolled airspace. No ATC authorization is required.", "img": null, "area": "air"}, {"id": 36, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class B airspace is indicated on the chart by:", "o": ["Solid Blue Lines", "Solid Magenta Lines", "Dashed Blue Lines"], "k": "Solid Blue Lines", "e": "Solid Blue lines denote Class B (Bravo) airspace.", "img": null, "area": "air"}, {"id": 37, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class D airspace is indicated on the chart by:", "o": ["Dashed Blue Lines", "Dashed Magenta Lines", "Solid Blue Lines"], "k": "Dashed Blue Lines", "e": "Dashed Blue lines denote Class D (Delta) airspace.", "img": null, "area": "air"}, {"id": 38, "c": "Airspace", "a": "UA.II.A.K3", "q": "Prohibited Areas (P-xxxx) mean:", "o": ["Flight is prohibited", "Flight is allowed with permission", "Military training"], "k": "Flight is prohibited", "e": "Flight in Prohibited areas (e.g., Camp David) is strictly forbidden.", "img": null, "area": "air"}, {"id": 39, "c": "Airspace", "a": "UA.II.A.K3", "q": "An Alert Area (A-xxxx) signifies:", "o": ["High volume of pilot training or unusual activity", "Missile firing", "No flight allowed"], "k": "High volume of pilot training or unusual activity", "e": "Alert areas contain high volumes of training. Pilots should be alert but entry is not restricted.", "img": null, "area": "air"}, {"id": 40, "c": "Airspace", "a": "UA.II.A.K3", "q": "A Warning Area (W-xxxx) is usually found:", "o": ["Over domestic waters (3NM outward)", "Over land", "Around airports"], "k": "Over domestic waters (3NM outward)", "e": "Warning areas are airspace of defined dimensions, extending from 3 nautical miles outward from the coast.", "img": null, "area": "air"}, {"id": 41, "c": "Airspace", "a": "UA.II.A.K2", "q": "What indicates the 'Ceiling' of Class D airspace in brackets, e.g., [25]?", "o": ["2,500 feet MSL", "250 feet AGL", "2,500 feet AGL"], "k": "2,500 feet MSL", "e": "Numbers in brackets indicate the ceiling of the airspace in hundreds of feet MSL.", "img": null, "area": "air"}, {"id": 42, "c": "Airspace", "a": "UA.II.A.K2", "q": "If the ceiling number in brackets has a minus sign [-25], it means:", "o": ["Up to but not including 2,500 MSL", "Up to and including 2,500 MSL", "Below 25 feet"], "k": "Up to but not including 2,500 MSL", "e": "A minus sign means the airspace extends up to but does not include that altitude.", "img": null, "area": "air"}, {"id": 43, "c": "Airspace", "a": "UA.I.B.K23", "q": "Which airspace requires a transponder (Mode C/ADS-B)?", "o": ["Class B and C", "Class D", "Class G"], "k": "Class B and C", "e": "Class B and C (and above 10k ft) require transponders for manned aircraft, though drones often just need authorization.", "img": null, "area": "air"}, {"id": 44, "c": "Airspace", "a": "UA.II.A.K2", "q": "The height of an obstruction is shown as 1234 (400). What is 1234?", "o": ["MSL height", "AGL height", "Distance"], "k": "MSL height", "e": "The top number is Mean Sea Level (MSL). The number in parentheses is Above Ground Level (AGL).", "img": null, "area": "air"}, {"id": 45, "c": "Airspace", "a": "UA.II.A.K2", "q": "What does a flag symbol on a sectional chart indicate?", "o": ["Visual Checkpoint (VFR Checkpoint)", "Airport", "Obstruction"], "k": "Visual Checkpoint (VFR Checkpoint)", "e": "Flags mark visual checkpoints used by manned pilots to report location.", "img": null, "area": "air"}, {"id": 46, "c": "Airspace", "a": "UA.II.A.K2", "q": "A tick mark on an airport symbol indicates:", "o": ["Fuel is available", "It is abandoned", "It is private"], "k": "Fuel is available", "e": "Tick marks around the airport circle indicate fuel is available during normal hours.", "img": null, "area": "air"}, {"id": 47, "c": "Airspace", "a": "UA.II.A.K2", "q": "An airport symbol with an 'R' implies:", "o": ["Private/Restricted", "Runway lighted", "Radar services"], "k": "Private/Restricted", "e": "An 'R' in the circle (or specifically described) usually denotes a private or restricted airport.", "img": null, "area": "air"}, {"id": 48, "c": "Airspace", "a": "UA.II.A.K3", "q": "What is a TRSA (Terminal Radar Service Area)?", "o": ["Voluntary radar service area", "Mandatory Class B", "Prohibited area"], "k": "Voluntary radar service area", "e": "TRSA provides radar services but participation is voluntary for VFR pilots (solid grey lines).", "img": null, "area": "air"}, {"id": 49, "c": "Airspace", "a": "UA.II.A.K3", "q": "Can you fly in a MOA (Military Operations Area)?", "o": ["Yes, but exercise extreme caution", "No, never", "Only with ATC permission"], "k": "Yes, but exercise extreme caution", "e": "VFR flights (including drones) can fly in an MOA without clearance, but it is dangerous due to military training.", "img": null, "area": "air"}, {"id": 50, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class E airspace starting at 1200 ft AGL is depicted by:", "o": ["Shaded Blue Line (Vignette)", "Shaded Magenta Line", "Dashed Blue Line"], "k": "Shaded Blue Line (Vignette)", "e": "Shaded Blue indicates Class E starts at 1200 ft AGL (Transition area).", "img": null, "area": "air"}, {"id": 51, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "Refer to the image. What does this sign indicate?", "o": ["Runway Holding Position", "Taxiway Location", "Runway Approach Area"], "k": "Runway Holding Position", "e": "Red background with white text indicates a mandatory instruction, specifically a Runway Holding Position. Stop here unless cleared.", "img": "demo-hold-sign", "area": "ops"}, {"id": 52, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "Which leg of the traffic pattern is flown parallel to the runway, opposite the direction of landing?", "o": ["Downwind leg", "Base leg", "Crosswind leg"], "k": "Downwind leg", "e": "The Downwind leg is flown parallel to the landing runway in the opposite direction.", "img": null, "area": "ops"}, {"id": 53, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "The standard direction of turns in a traffic pattern is:", "o": ["Left", "Right", "Straight in"], "k": "Left", "e": "Standard traffic patterns use left turns unless visual markings or the Chart Supplement indicate otherwise.", "img": null, "area": "ops"}, {"id": 54, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "What is the frequency usually used at a non-towered airport for pilots to self-announce?", "o": ["CTAF (Common Traffic Advisory Frequency)", "UNICOM", "AWOS"], "k": "CTAF (Common Traffic Advisory Frequency)", "e": "CTAF is used for self-announcing position and intentions at non-towered airports.", "img": null, "area": "ops"}, {"id": 55, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "A runway marked '9' is oriented toward which magnetic direction?", "o": ["090 degrees (East)", "009 degrees", "180 degrees"], "k": "090 degrees (East)", "e": "Runways are numbered by their magnetic heading divided by 10. Runway 9 = 090 degrees.", "img": null, "area": "ops"}, {"id": 56, "c": "Airport Ops", "a": "UA.I.B.K16", "q": "Who has the right of way?", "o": ["Manned Aircraft", "The sUAS", "Whichever is on the right"], "k": "Manned Aircraft", "e": "sUAS must always yield right of way to all manned aircraft.", "img": null, "area": "ops"}, {"id": 57, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "If you hear 'Traffic 10 o'clock', where should you look?", "o": ["Front-Left", "Front-Right", "Directly Behind"], "k": "Front-Left", "e": "12 o'clock is straight ahead. 9 o'clock is left. 10 o'clock is slightly left.", "img": null, "area": "ops"}, {"id": 58, "c": "Airport Ops", "a": "UA.V.C.K1", "q": "How should you scan for traffic?", "o": ["Short, regularly spaced eye movements", "Continuous sweeping motion", "Focus on the horizon"], "k": "Short, regularly spaced eye movements", "e": "Focus on different segments of the sky for short intervals (10 degrees at a time).", "img": null, "area": "ops"}, {"id": 59, "c": "Airport Ops", "a": "UA.V.C.K1", "q": "Most mid-air collisions occur during:", "o": ["Clear days near airports", "Night time", "Foggy weather"], "k": "Clear days near airports", "e": "Most collisions happen in good VFR weather, often near airports/navaids.", "img": null, "area": "ops"}, {"id": 60, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "A remote pilot operating near a non-towered airport should:", "o": ["Monitor the CTAF frequency", "Call the nearest tower", "Fly immediately to 400ft"], "k": "Monitor the CTAF frequency", "e": "It is best practice (though not strictly mandatory if no radio) to monitor CTAF for situational awareness.", "img": null, "area": "ops"}, {"id": 61, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "Runway markings are what color?", "o": ["White", "Yellow", "Red"], "k": "White", "e": "Runway markings are white. Taxiway markings are yellow.", "img": null, "area": "ops"}, {"id": 62, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "Taxiway markings are what color?", "o": ["Yellow", "White", "Blue"], "k": "Yellow", "e": "Taxiways are marked with yellow centerlines.", "img": null, "area": "ops"}, {"id": 63, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "A 'Chevrons' marking on a runway threshold indicates:", "o": ["Area unfit for landing/takeoff/taxi", "Displaced Threshold", "Blast Pad"], "k": "Area unfit for landing/takeoff/taxi", "e": "Chevrons (yellow arrows) indicate a blast pad or stopway that cannot be used for taxi, takeoff, or landing.", "img": null, "area": "ops"}, {"id": 64, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "A white arrow pointing down the runway center line before the number indicates:", "o": ["Displaced Threshold (Taxi/Takeoff allowed)", "Closed Runway", "Short Runway"], "k": "Displaced Threshold (Taxi/Takeoff allowed)", "e": "Arrows indicate a displaced threshold. You can taxi/takeoff there, but not land.", "img": null, "area": "ops"}, {"id": 65, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "A large 'X' on a runway means:", "o": ["Runway Closed", "Helicopter pad", "Experimental"], "k": "Runway Closed", "e": "A yellow X means the runway is closed to all operations.", "img": null, "area": "ops"}, {"id": 66, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "What indicates a civilian land airport beacon?", "o": ["Green and White flashes", "White and Yellow", "Green and two Whites"], "k": "Green and White flashes", "e": "Civilian land airports flash White and Green.", "img": null, "area": "ops"}, {"id": 67, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "What indicates a Military airport beacon?", "o": ["Two White flashes, One Green", "White and Green", "Yellow and White"], "k": "Two White flashes, One Green", "e": "Dual-peaked (two quick) white flashes between green flashes indicate a military airport.", "img": null, "area": "ops"}, {"id": 68, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "The phrase 'Line Up and Wait' means:", "o": ["Taxi onto runway and wait", "Wait at the hold short line", "Takeoff immediately"], "k": "Taxi onto runway and wait", "e": "ATC instruction to enter the runway and wait for clearance. Do not takeoff.", "img": null, "area": "ops"}, {"id": 69, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "UNICOM is typically used for:", "o": ["Non-flight services (fuel, car rental)", "ATC control", "Weather only"], "k": "Non-flight services (fuel, car rental)", "e": "UNICOM is a base station that provides info on services, wind, etc., at non-towered airports.", "img": null, "area": "ops"}, {"id": 70, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "ATIS (Automatic Terminal Information Service) provides:", "o": ["Recorded weather and airport data", "Traffic control", "Emergency services"], "k": "Recorded weather and airport data", "e": "ATIS is a continuous loop recording of local weather and airport conditions.", "img": null, "area": "ops"}, {"id": 71, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "The traffic pattern altitude (TPA) is generally:", "o": ["1000 ft AGL", "500 ft AGL", "1500 ft AGL"], "k": "1000 ft AGL", "e": "Standard TPA is 1000 feet AGL unless otherwise noted.", "img": null, "area": "ops"}, {"id": 72, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "What is the 'Base' leg?", "o": ["Perpendicular to runway, before final", "Parallel to runway", "Departure leg"], "k": "Perpendicular to runway, before final", "e": "Base leg is the transition between Downwind and Final approach.", "img": null, "area": "ops"}, {"id": 73, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "A 'Segmented Circle' provides info on:", "o": ["Traffic pattern direction", "Wind direction", "Runway location"], "k": "Traffic pattern direction", "e": "Segmented circles show traffic pattern indicators (L-shape) to show left or right turns.", "img": null, "area": "ops"}, {"id": 74, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "If a pilot announces 'Left Downwind for Runway 36', they are:", "o": ["West of the runway, flying south", "East of the runway, flying south", "North of the runway"], "k": "West of the runway, flying south", "e": "Runway 36 heads north. Left traffic means left turns, so the pattern is on the west side, and downwind is flown southbound.", "img": null, "area": "ops"}, {"id": 75, "c": "Airport Ops", "a": "UA.II.A.K3", "q": "What is a TFR (Temporary Flight Restriction)?", "o": ["Short term restriction (VIP, Disaster)", "Permanent restriction", "Training area"], "k": "Short term restriction (VIP, Disaster)", "e": "TFRs are temporary bans for things like President travel, wildfires, or Super Bowls.", "img": null, "area": "ops"}, {"id": 76, "c": "Weather", "a": "UA.III.B.K1", "q": "What are the characteristics of a stable air mass?", "o": ["Stratiform clouds, fog, smooth air", "Cumulus clouds, turbulence", "Showery precipitation"], "k": "Stratiform clouds, fog, smooth air", "e": "Stable air resists vertical motion, leading to flat (stratiform) clouds and poor visibility but smooth air.", "img": null, "area": "wx"}, {"id": 77, "c": "Weather", "a": "UA.III.B.K1", "q": "What are the characteristics of an unstable air mass?", "o": ["Turbulence, good visibility, cumulus clouds", "Smooth air, poor visibility", "Steady rain"], "k": "Turbulence, good visibility, cumulus clouds", "e": "Unstable air rises easily, creating vertical clouds (cumulus) and turbulence, but clears out haze (good visibility).", "img": null, "area": "wx"}, {"id": 78, "c": "Weather", "a": "UA.III.B.K1", "q": "What is 'Density Altitude'?", "o": ["Pressure altitude corrected for non-standard temperature", "Height above the ground", "Height above sea level"], "k": "Pressure altitude corrected for non-standard temperature", "e": "Density altitude is how the aircraft 'feels' the air. High density altitude = poor performance.", "img": null, "area": "wx"}, {"id": 79, "c": "Weather", "a": "UA.III.B.K1", "q": "High humidity will do what to aircraft performance?", "o": ["Decrease performance", "Increase performance", "No effect"], "k": "Decrease performance", "e": "Water vapor is lighter than dry air, making the air less dense. Less dense air = reduced lift/power.", "img": null, "area": "wx"}, {"id": 80, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'OVC007' means:", "o": ["Overcast skies at 700 feet", "Overcast skies at 7,000 feet", "Visibility 7 miles"], "k": "Overcast skies at 700 feet", "e": "Altitudes in METARs are in hundreds of feet. 007 = 700 ft.", "img": null, "area": "wx"}, {"id": 81, "c": "Weather", "a": "UA.III.B.K1", "q": "What is standard sea-level pressure?", "o": ["29.92 inches of mercury (1013.2 mb)", "30.92 inches of mercury", "28.92 inches of mercury"], "k": "29.92 inches of mercury (1013.2 mb)", "e": "The standard atmosphere at sea level is 29.92 inHg, or 1013.2 millibars, at 15 C.", "img": null, "area": "wx"}, {"id": 82, "c": "Weather", "a": "UA.III.B.K1", "q": "Thunderstorms reach their greatest intensity during which stage?", "o": ["Mature stage", "Cumulus stage", "Dissipating stage"], "k": "Mature stage", "e": "The mature stage is characterized by rain reaching the surface and violent turbulence.", "img": null, "area": "wx"}, {"id": 83, "c": "Weather", "a": "UA.III.B.K1", "q": "Which type of fog forms when moist air moves over colder ground?", "o": ["Advection fog", "Radiation fog", "Upslope fog"], "k": "Advection fog", "e": "Advection fog requires wind to move moist air over a cold surface (common in coastal areas).", "img": null, "area": "wx"}, {"id": 84, "c": "Weather", "a": "UA.III.B.K1", "q": "Which type of fog forms on clear, calm nights?", "o": ["Radiation fog", "Advection fog", "Steam fog"], "k": "Radiation fog", "e": "Radiation fog forms when the ground cools rapidly at night, cooling the air above it.", "img": null, "area": "wx"}, {"id": 85, "c": "Weather", "a": "UA.III.B.K1", "q": "Wind shear can occur:", "o": ["At all altitudes", "Only at high altitudes", "Only near the ground"], "k": "At all altitudes", "e": "Wind shear (sudden change in wind speed/direction) can happen at any altitude.", "img": null, "area": "wx"}, {"id": 86, "c": "Weather", "a": "UA.III.A.K2", "q": "METAR 'VRB04KT' means:", "o": ["Wind variable at 4 knots", "Visibility 4 miles", "Vertical visibility 400"], "k": "Wind variable at 4 knots", "e": "VRB means variable direction. 04KT means 4 knots speed.", "img": null, "area": "wx"}, {"id": 87, "c": "Weather", "a": "UA.III.A.K2", "q": "In a TAF, 'FM' (From) indicates:", "o": ["Rapid change in conditions", "Gradual change", "Temporary change"], "k": "Rapid change in conditions", "e": "FM indicates a rapid/significant change occurring at that time.", "img": null, "area": "wx"}, {"id": 88, "c": "Weather", "a": "UA.III.A.K2", "q": "In a TAF, 'BECMG' (Becoming) indicates:", "o": ["Gradual change over time", "Rapid change", "Probability"], "k": "Gradual change over time", "e": "BECMG indicates a gradual change over the specified period.", "img": null, "area": "wx"}, {"id": 89, "c": "Weather", "a": "UA.III.B.K1", "q": "Low-level wind shear is most dangerous during:", "o": ["Takeoff and Landing", "Cruise", "Hover"], "k": "Takeoff and Landing", "e": "Sudden changes in lift near the ground can cause accidents.", "img": null, "area": "wx"}, {"id": 90, "c": "Weather", "a": "UA.III.B.K1", "q": "Dew point is:", "o": ["Temperature at which air becomes saturated", "Current air temperature", "Freezing point"], "k": "Temperature at which air becomes saturated", "e": "When temperature drops to the dew point, water condenses, forming dew, fog, or clouds.", "img": null, "area": "wx"}, {"id": 91, "c": "Weather", "a": "UA.III.B.K1", "q": "If Temperature and Dew Point converge, what can you expect?", "o": ["Fog or Clouds", "Clear skies", "High winds"], "k": "Fog or Clouds", "e": "A small Temp-Dew Point spread means the air is near saturation.", "img": null, "area": "wx"}, {"id": 92, "c": "Weather", "a": "UA.III.A.K2", "q": "METAR 'P0002' means:", "o": ["0.02 inches of precipitation in last hour", "Pressure 00.02", "Probability 2%"], "k": "0.02 inches of precipitation in last hour", "e": "P followed by 4 digits indicates precipitation in hundredths of an inch.", "img": null, "area": "wx"}, {"id": 93, "c": "Weather", "a": "UA.III.A.K2", "q": "What does 'A2992' mean in a METAR?", "o": ["Altimeter 29.92 inHg", "Altitude 2,992 ft", "Visibility 29.92"], "k": "Altimeter 29.92 inHg", "e": "A stands for Altimeter setting in inches of mercury.", "img": null, "area": "wx"}, {"id": 94, "c": "Weather", "a": "UA.III.A.K2", "q": "What does 'TSRA' mean?", "o": ["Thunderstorm with Rain", "Tropical Storm", "Tower Rain"], "k": "Thunderstorm with Rain", "e": "TS = Thunderstorm, RA = Rain.", "img": null, "area": "wx"}, {"id": 95, "c": "Weather", "a": "UA.III.A.K2", "q": "What does 'BR' mean in a METAR?", "o": ["Mist", "Broken Clouds", "Breeze"], "k": "Mist", "e": "BR is the code for Mist (French 'Brume').", "img": null, "area": "wx"}, {"id": 96, "c": "Weather", "a": "UA.III.B.K1", "q": "A 'Temperature Inversion' results in:", "o": ["Stable air, poor visibility", "Unstable air", "Thunderstorms"], "k": "Stable air, poor visibility", "e": "An inversion traps pollutants and moisture near the surface, creating haze/fog.", "img": null, "area": "wx"}, {"id": 97, "c": "Weather", "a": "UA.III.B.K1", "q": "Which front moves the fastest?", "o": ["Cold Front", "Warm Front", "Stationary Front"], "k": "Cold Front", "e": "Cold fronts are dense and push under warm air, typically moving faster than warm fronts.", "img": null, "area": "wx"}, {"id": 98, "c": "Weather", "a": "UA.III.B.K1", "q": "Squall lines are associated with:", "o": ["Fast-moving cold fronts", "Warm fronts", "High pressure"], "k": "Fast-moving cold fronts", "e": "Squall lines are narrow bands of intense thunderstorms often ahead of cold fronts.", "img": null, "area": "wx"}, {"id": 99, "c": "Weather", "a": "UA.III.A.K2", "q": "TAF reports are valid for:", "o": ["Usually 24 or 30 hours", "1 hour", "7 days"], "k": "Usually 24 or 30 hours", "e": "Terminal Aerodrome Forecasts are generally issued 4 times daily and valid for 24/30 hours.", "img": null, "area": "wx"}, {"id": 100, "c": "Weather", "a": "UA.III.A.K2", "q": "A METAR is issued:", "o": ["Hourly (or special)", "Daily", "Weekly"], "k": "Hourly (or special)", "e": "METARs are routine observations issued hourly, plus SPECI reports for sudden changes.", "img": null, "area": "wx"}, {"id": 101, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "If the Center of Gravity (CG) is too far aft, the aircraft will be:", "o": ["Unstable and difficult to recover from stalls", "More stable", "Nose heavy"], "k": "Unstable and difficult to recover from stalls", "e": "An aft CG makes the aircraft less stable and can make stall recovery impossible.", "img": null, "area": "perf"}, {"id": 102, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "If the CG is too far forward, the aircraft will:", "o": ["Require more lift/drag and may lack elevator authority", "Be unstable", "Fly faster"], "k": "Require more lift/drag and may lack elevator authority", "e": "Forward CG creates a nose-heavy condition. The tail must push down more, increasing effective weight/drag.", "img": null, "area": "perf"}, {"id": 103, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "The 'Moment' of a load is calculated by:", "o": ["Weight x Arm", "Weight / Arm", "Arm / Weight"], "k": "Weight x Arm", "e": "Moment = Weight × Arm (distance from datum).", "img": null, "area": "perf"}, {"id": 104, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "High Density Altitude causes:", "o": ["Reduced propeller and wing efficiency", "Increased lift", "Better battery life"], "k": "Reduced propeller and wing efficiency", "e": "Thin air at high density altitude reduces thrust and lift.", "img": null, "area": "perf"}, {"id": 105, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "What factors increase Density Altitude?", "o": ["High Temp, High Humidity, High Elevation", "Low Temp, Low Elevation", "High Pressure"], "k": "High Temp, High Humidity, High Elevation", "e": "Hot, High, Humid = High Density Altitude (poor performance).", "img": null, "area": "perf"}, {"id": 106, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Adding weight to a drone will:", "o": ["Increase stall speed and decrease flight time", "Decrease stall speed", "Increase flight time"], "k": "Increase stall speed and decrease flight time", "e": "More weight requires more lift/thrust, consuming more power and increasing stall speed for fixed wings.", "img": null, "area": "perf"}, {"id": 107, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Battery performance is significantly reduced by:", "o": ["Cold Temperatures", "Warm Temperatures", "High Humidity"], "k": "Cold Temperatures", "e": "Lithium batteries lose voltage/capacity in cold weather.", "img": null, "area": "perf"}, {"id": 108, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "What is 'Load Factor'?", "o": ["Ratio of lift to weight (G-force)", "Cargo weight", "Battery capacity"], "k": "Ratio of lift to weight (G-force)", "e": "Load factor is the ratio of aerodynamic load (lift) to gross weight. 2G = twice the weight.", "img": null, "area": "perf"}, {"id": 109, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A 60-degree bank turn produces approximately how much load factor?", "o": ["2 Gs", "1.4 Gs", "3 Gs"], "k": "2 Gs", "e": "At 60 degrees of bank, load factor doubles (2G), increasing stall speed.", "img": null, "area": "perf"}, {"id": 110, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Increased load factor causes stall speed to:", "o": ["Increase", "Decrease", "Stay same"], "k": "Increase", "e": "The wing must produce more lift to support the effective weight, so it stalls at a higher speed.", "img": null, "area": "perf"}, {"id": 111, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Best practice for LiPo battery storage is:", "o": ["Storage charge (~50-60%) in cool place", "Fully charged", "Fully drained"], "k": "Storage charge (~50-60%) in cool place", "e": "Storing LiPos at full charge or empty damages them. Use storage voltage (~3.8V/cell).", "img": null, "area": "perf"}, {"id": 112, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A damaged/swollen LiPo battery should be:", "o": ["Removed from service and disposed safely", "Charged slowly", "Used until dead"], "k": "Removed from service and disposed safely", "e": "Swelling indicates internal damage and fire risk.", "img": null, "area": "perf"}, {"id": 113, "c": "Loading & Performance", "a": "UA.IV.A.K2", "q": "Which environmental factor affects battery voltage?", "o": ["Temperature", "Wind direction", "Cloud cover"], "k": "Temperature", "e": "Cold weather causes voltage sag in lithium batteries.", "img": null, "area": "perf"}, {"id": 114, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Manufacturer weight limits should be:", "o": ["Strictly followed", "Exceeded by 10%", "Ignored for short flights"], "k": "Strictly followed", "e": "Operating outside manufacturer limits can compromise flight control and violates safe operation requirements.", "img": null, "area": "perf"}, {"id": 115, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A 'Datum' is:", "o": ["Reference point for measuring arms", "Total weight", "CG location"], "k": "Reference point for measuring arms", "e": "The Datum is the imaginary vertical plane from which all horizontal distances (arms) are measured.", "img": null, "area": "perf"}, {"id": 116, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "To calculate CG location:", "o": ["Total Moment / Total Weight", "Total Weight / Total Moment", "Weight x Arm"], "k": "Total Moment / Total Weight", "e": "CG = Sum of Moments divided by Total Weight.", "img": null, "area": "perf"}, {"id": 117, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A drone operated above its maximum takeoff weight may:", "o": ["Fail to maintain altitude or control", "Fly faster", "Have better stability"], "k": "Fail to maintain altitude or control", "e": "Excess weight can overload motors and reduce control authority.", "img": null, "area": "perf"}, {"id": 118, "c": "Loading & Performance", "a": "UA.IV.A.K2", "q": "Wind affects battery consumption by:", "o": ["Increasing power needed to hold position/fly upwind", "Decreasing power usage", "No effect"], "k": "Increasing power needed to hold position/fly upwind", "e": "Motors must work harder against wind, increasing current draw.", "img": null, "area": "perf"}, {"id": 119, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "An aft CG generally results in:", "o": ["Lower stability", "Higher stability", "No effect"], "k": "Lower stability", "e": "Aft CG reduces the restoring tendency of the aircraft, making it pitch-sensitive.", "img": null, "area": "perf"}, {"id": 120, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "The term 'Arm' refers to:", "o": ["Distance from datum to weight", "Weight of item", "Center of lift"], "k": "Distance from datum to weight", "e": "Arm is the horizontal distance from the reference datum to the center of gravity of an item.", "img": null, "area": "perf"}, {"id": 121, "c": "Operations", "a": "UA.V.A.K2", "q": "'Hyperventilation' is caused by:", "o": ["Excessive breathing (loss of CO2)", "Lack of oxygen", "High altitude"], "k": "Excessive breathing (loss of CO2)", "e": "Rapid breathing lowers CO2 levels. Treatment: slow breathing, talk aloud, breathe into bag if appropriate.", "img": null, "area": "ops"}, {"id": 122, "c": "Operations", "a": "UA.V.A.K2", "q": "Symptoms of Hyperventilation can be similar to:", "o": ["Hypoxia", "Dehydration", "Motion sickness"], "k": "Hypoxia", "e": "Both can cause dizziness, tingling, and confusion. If at altitude, descend and breathe normally.", "img": null, "area": "ops"}, {"id": 123, "c": "Operations", "a": "UA.V.A.K2", "q": "Alcohol affects pilots by:", "o": ["Impairing judgment and reaction time", "Improving confidence safely", "No effect after 4 hours"], "k": "Impairing judgment and reaction time", "e": "Even small amounts of alcohol degrade vision, judgment, and coordination.", "img": null, "area": "ops"}, {"id": 124, "c": "Operations", "a": "UA.V.A.K2", "q": "'Get-there-itis' is an example of:", "o": ["External Pressure", "Resignation", "Machismo"], "k": "External Pressure", "e": "The desire to complete a mission despite risks is driven by external/internal pressure to arrive.", "img": null, "area": "ops"}, {"id": 125, "c": "Operations", "a": "UA.V.A.K2", "q": "The 'IMSAFE' checklist includes:", "o": ["Illness, Medication, Stress, Alcohol, Fatigue, Emotion", "Inspection, Maintenance, Safety, Airspace, Fuel, Equipment", "Instrument, Map, Signal, Altitude, Flight, Emergency"], "k": "Illness, Medication, Stress, Alcohol, Fatigue, Emotion", "e": "IMSAFE is a personal readiness checklist for pilots.", "img": null, "area": "ops"}, {"id": 126, "c": "Operations", "a": "UA.V.A.K2", "q": "The 'PAVE' checklist includes:", "o": ["Pilot, Aircraft, enVironment, External pressures", "Plan, Act, Verify, Execute", "Pilot, Airspace, Visibility, Equipment"], "k": "Pilot, Aircraft, enVironment, External pressures", "e": "PAVE is used for risk management before flight.", "img": null, "area": "ops"}, {"id": 127, "c": "Operations", "a": "UA.V.A.K2", "q": "The DECIDE model is used for:", "o": ["Aeronautical Decision Making", "Battery calculation", "Weather forecasting"], "k": "Aeronautical Decision Making", "e": "Detect, Estimate, Choose, Identify, Do, Evaluate.", "img": null, "area": "ops"}, {"id": 128, "c": "Operations", "a": "UA.V.A.K2", "q": "The hazardous attitude 'Macho' has the antidote:", "o": ["Taking chances is foolish", "It could happen to me", "Follow the rules"], "k": "Taking chances is foolish", "e": "Macho: 'I can do it.' Antidote: 'Taking chances is foolish.'", "img": null, "area": "ops"}, {"id": 129, "c": "Operations", "a": "UA.V.A.K2", "q": "The hazardous attitude 'Invulnerability' antidote is:", "o": ["It could happen to me", "Taking chances is foolish", "Not so fast"], "k": "It could happen to me", "e": "Invulnerability: 'It won't happen to me.' Antidote: 'It could happen to me.'", "img": null, "area": "ops"}, {"id": 130, "c": "Operations", "a": "UA.V.A.K2", "q": "The hazardous attitude 'Anti-authority' antidote is:", "o": ["Follow the rules; they are usually right", "It could happen to me", "I am not helpless"], "k": "Follow the rules; they are usually right", "e": "Anti-authority: 'Don't tell me.' Antidote: 'Follow the rules. They are usually right.'", "img": null, "area": "ops"}, {"id": 131, "c": "Operations", "a": "UA.V.A.K2", "q": "The hazardous attitude 'Impulsivity' antidote is:", "o": ["Not so fast; think first", "Do it quickly", "It could happen to me"], "k": "Not so fast; think first", "e": "Impulsivity: 'Do something quickly.' Antidote: 'Not so fast. Think first.'", "img": null, "area": "ops"}, {"id": 132, "c": "Operations", "a": "UA.V.A.K2", "q": "The hazardous attitude 'Resignation' antidote is:", "o": ["I am not helpless; I can make a difference", "What's the use", "Follow the rules"], "k": "I am not helpless; I can make a difference", "e": "Resignation: 'What's the use?' Antidote: 'I am not helpless. I can make a difference.'", "img": null, "area": "ops"}, {"id": 133, "c": "Operations", "a": "UA.V.A.K2", "q": "Stress can be categorized as:", "o": ["Acute and Chronic", "Good and Bad only", "Physical only"], "k": "Acute and Chronic", "e": "Acute stress is short-term response; Chronic stress builds over time and degrades performance.", "img": null, "area": "ops"}, {"id": 134, "c": "Operations", "a": "UA.V.A.K2", "q": "Fatigue is best combated by:", "o": ["Adequate sleep", "Caffeine", "Adrenaline"], "k": "Adequate sleep", "e": "There is no substitute for sleep. Caffeine is a temporary aid, not a cure.", "img": null, "area": "ops"}, {"id": 136, "c": "Operations", "a": "UA.V.A.K2", "q": "Flicker vertigo is caused by:", "o": ["Flashing light through propellers at certain frequencies", "Spinning rapidly", "High altitude"], "k": "Flashing light through propellers at certain frequencies", "e": "Light flickering at 4-20 Hz can cause nausea, dizziness, or seizures in susceptible people.", "img": null, "area": "ops"}, {"id": 137, "c": "Operations", "a": "UA.V.A.K2", "q": "Who has final authority for the operation?", "o": ["Remote PIC", "Visual Observer", "Client"], "k": "Remote PIC", "e": "The Remote Pilot in Command is directly responsible for and final authority as to the operation of the sUAS.", "img": null, "area": "ops"}, {"id": 138, "c": "Operations", "a": "UA.V.A.K3", "q": "Crew Resource Management (CRM) focuses on:", "o": ["Effective communication and use of all resources", "Managing batteries", "Controlling ATC"], "k": "Effective communication and use of all resources", "e": "CRM improves safety by using people, equipment, and information effectively.", "img": null, "area": "ops"}, {"id": 139, "c": "Operations", "a": "UA.V.A.K3", "q": "Before flight, the Remote PIC must brief:", "o": ["All participants on operating conditions, emergencies, roles", "Only the Visual Observer", "Nobody"], "k": "All participants on operating conditions, emergencies, roles", "e": "A crew briefing ensures everyone understands hazards and responsibilities.", "img": null, "area": "ops"}, {"id": 140, "c": "Operations", "a": "UA.V.A.K3", "q": "If a VO loses sight of the drone, they should:", "o": ["Immediately inform the Remote PIC", "Wait 30 seconds", "Move without telling anyone"], "k": "Immediately inform the Remote PIC", "e": "Communication is critical. The PIC must know immediately if VLOS is lost.", "img": null, "area": "ops"}, {"id": 141, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Who is responsible for determining the drone is safe for operation?", "o": ["Remote PIC", "Manufacturer", "FAA Inspector"], "k": "Remote PIC", "e": "Before every flight, the Remote PIC must ensure the aircraft is in a condition for safe operation.", "img": null, "area": "ops"}, {"id": 142, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Maintenance records for sUAS under Part 107 are:", "o": ["Recommended but not specifically required by Part 107", "Required for 1 year", "Required for 5 years"], "k": "Recommended but not specifically required by Part 107", "e": "While Part 107 does not mandate logs like manned aircraft, keeping maintenance records is a safety best practice.", "img": null, "area": "ops"}, {"id": 143, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "After maintenance, who determines if the aircraft is safe to fly?", "o": ["Remote PIC", "Mechanic", "Owner"], "k": "Remote PIC", "e": "The Remote PIC is ultimately responsible for safe condition before operation.", "img": null, "area": "ops"}, {"id": 144, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Cracks or damage in propellers can cause:", "o": ["Catastrophic failure", "Better lift", "Only vibration"], "k": "Catastrophic failure", "e": "Damaged props can fail under load, causing immediate loss of control.", "img": null, "area": "ops"}, {"id": 145, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "A preflight inspection should include:", "o": ["Airframe, props, battery, control links, firmware status", "Only battery level", "Only propellers"], "k": "Airframe, props, battery, control links, firmware status", "e": "A comprehensive preflight ensures all critical systems are ready.", "img": null, "area": "ops"}, {"id": 146, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "If a manufacturer issues a safety bulletin:", "o": ["You should comply/review before flight", "Ignore it", "Wait for FAA mandate"], "k": "You should comply/review before flight", "e": "Manufacturer guidance is essential for continued safe operation.", "img": null, "area": "ops"}, {"id": 147, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "A compass calibration should be performed:", "o": ["When prompted or environment/location changes significantly", "Before every flight always", "Never"], "k": "When prompted or environment/location changes significantly", "e": "Unnecessary calibrations can introduce errors. Follow manufacturer guidance.", "img": null, "area": "ops"}, {"id": 148, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Firmware updates should be:", "o": ["Tested before operational mission", "Installed immediately on site", "Ignored"], "k": "Tested before operational mission", "e": "Updates can change behavior. Test them in a safe environment before critical operations.", "img": null, "area": "ops"}, {"id": 149, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Motor bearings should be checked for:", "o": ["Smooth rotation and unusual noise", "Paint color", "Temperature only"], "k": "Smooth rotation and unusual noise", "e": "Grinding, stiffness, or play indicates bearing wear.", "img": null, "area": "ops"}, {"id": 150, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Batteries should be inspected for:", "o": ["Swelling, damage, connector corrosion", "Only charge level", "Serial number"], "k": "Swelling, damage, connector corrosion", "e": "Physical battery damage can lead to fire or failure.", "img": null, "area": "ops"}, {"id": 151, "c": "Charts", "a": "UA.II.A.K2", "q": "What does a blue airport symbol indicate?", "o": ["Towered airport", "Non-towered airport", "Private airport"], "k": "Towered airport", "e": "Blue airport symbols indicate airports with an operating control tower.", "img": null, "area": "air"}, {"id": 152, "c": "Charts", "a": "UA.II.A.K2", "q": "What does a magenta airport symbol indicate?", "o": ["Non-towered airport", "Towered airport", "Military airport"], "k": "Non-towered airport", "e": "Magenta airport symbols indicate airports without a control tower.", "img": null, "area": "air"}, {"id": 153, "c": "Charts", "a": "UA.II.A.K2", "q": "Shaded magenta boundary means Class E begins at:", "o": ["700 ft AGL", "1200 ft AGL", "Surface"], "k": "700 ft AGL", "e": "Shaded magenta vignette = Class E floor 700 feet AGL.", "img": null, "area": "air"}, {"id": 154, "c": "Charts", "a": "UA.II.A.K2", "q": "Shaded blue boundary means Class E begins at:", "o": ["1200 ft AGL", "700 ft AGL", "Surface"], "k": "1200 ft AGL", "e": "Shaded blue vignette = Class E floor 1200 feet AGL.", "img": null, "area": "air"}, {"id": 155, "c": "Charts", "a": "UA.II.A.K2", "q": "Dashed magenta boundary means:", "o": ["Class E to Surface", "Class D", "Class B"], "k": "Class E to Surface", "e": "Dashed magenta encloses Class E airspace extending to the surface.", "img": null, "area": "air"}, {"id": 156, "c": "Charts", "a": "UA.II.A.K2", "q": "Dashed blue boundary means:", "o": ["Class D airspace", "Class E", "Class C"], "k": "Class D airspace", "e": "Dashed blue lines depict Class D airspace around towered airports.", "img": null, "area": "air"}, {"id": 157, "c": "Charts", "a": "UA.II.A.K2", "q": "Solid blue boundary means:", "o": ["Class B airspace", "Class C airspace", "Class D airspace"], "k": "Class B airspace", "e": "Solid blue lines depict Class B airspace.", "img": null, "area": "air"}, {"id": 158, "c": "Charts", "a": "UA.II.A.K2", "q": "Solid magenta boundary means:", "o": ["Class C airspace", "Class B", "Restricted Area"], "k": "Class C airspace", "e": "Solid magenta lines depict Class C airspace.", "img": null, "area": "air"}, {"id": 159, "c": "Charts", "a": "UA.II.A.K2", "q": "What does 'RP' next to an airport mean?", "o": ["Right Traffic Pattern", "Restricted Pilot", "Reporting Point"], "k": "Right Traffic Pattern", "e": "RP or 'RP' notation indicates right-hand traffic pattern for specified runway(s).", "img": null, "area": "air"}, {"id": 160, "c": "Charts", "a": "UA.II.A.K2", "q": "A star above airport data indicates:", "o": ["Rotating beacon operates sunset to sunrise", "Military airport", "Fuel available"], "k": "Rotating beacon operates sunset to sunrise", "e": "The star symbol indicates a rotating airport beacon.", "img": null, "area": "air"}, {"id": 161, "c": "Charts", "a": "UA.II.A.K2", "q": "An airport name followed by '(Pvt)' means:", "o": ["Private use airport", "Public airport", "Provisional airport"], "k": "Private use airport", "e": "(Pvt) denotes a private airport not open to general public use.", "img": null, "area": "air"}, {"id": 162, "c": "Charts", "a": "UA.II.A.K2", "q": "What does a parachute symbol indicate?", "o": ["Parachute Jumping Area", "Skydiving prohibited", "Military zone"], "k": "Parachute Jumping Area", "e": "The parachute symbol marks areas of frequent parachute jumping activity.", "img": null, "area": "air"}, {"id": 163, "c": "Charts", "a": "UA.II.A.K2", "q": "Glider operations are shown by:", "o": ["Glider symbol", "G letter", "Dashed circle"], "k": "Glider symbol", "e": "A glider silhouette denotes glider activity.", "img": null, "area": "air"}, {"id": 164, "c": "Charts", "a": "UA.II.A.K2", "q": "What does 'UC' next to an airport mean?", "o": ["Unicom frequency available", "Under construction", "Uncontrolled"], "k": "Under construction", "e": "UC indicates an airport or runway under construction.", "img": null, "area": "air"}, {"id": 165, "c": "Charts", "a": "UA.II.A.K2", "q": "A circle 'R' indicates:", "o": ["Restricted/Private airport", "Radar", "Right traffic"], "k": "Restricted/Private airport", "e": "Circled R or related annotation can indicate private/restricted use.", "img": null, "area": "air"}, {"id": 166, "c": "Charts", "a": "UA.II.A.K2", "q": "Numbers like 130 (45) next to tower mean:", "o": ["130 ft MSL, 45 ft AGL", "130 ft AGL, 45 ft MSL", "Frequency"], "k": "130 ft MSL, 45 ft AGL", "e": "Top number is elevation MSL; parentheses is height AGL.", "img": null, "area": "air"}, {"id": 167, "c": "Charts", "a": "UA.II.A.K2", "q": "Maximum Elevation Figure (MEF) '32' means:", "o": ["3,200 ft MSL", "320 ft AGL", "32,000 ft"], "k": "3,200 ft MSL", "e": "MEF is shown in hundreds of feet MSL. '32' = 3,200 feet MSL.", "img": null, "area": "air"}, {"id": 168, "c": "Charts", "a": "UA.II.A.K2", "q": "What does 'L' after runway length mean?", "o": ["Runway lights available", "Long runway", "Left traffic"], "k": "Runway lights available", "e": "L indicates runway lighting.", "img": null, "area": "air"}, {"id": 169, "c": "Charts", "a": "UA.II.A.K2", "q": "What does 'FSS' refer to?", "o": ["Flight Service Station", "Flight Safety System", "Federal Sky Service"], "k": "Flight Service Station", "e": "FSS provides weather briefings, flight planning, and other pilot services.", "img": null, "area": "air"}, {"id": 170, "c": "Charts", "a": "UA.II.A.K2", "q": "CTAF frequency is used for:", "o": ["Self-announce at non-towered airports", "ATC clearance", "Emergency only"], "k": "Self-announce at non-towered airports", "e": "Common Traffic Advisory Frequency is for pilots to announce position and intentions.", "img": null, "area": "air"}, {"id": 171, "c": "Regulations", "a": "UA.I.B.K1", "q": "A person whose sole task is watching the sUAS to assist the remote pilot is called:", "o": ["Visual Observer", "Ground Crew", "Safety Pilot"], "k": "Visual Observer", "e": "A visual observer (VO) helps the Remote PIC maintain visual line of sight and situational awareness.", "img": null, "area": "regs"}, {"id": 172, "c": "Regulations", "a": "UA.I.A.K4", "q": "If requested by the FAA, a remote pilot must present their Remote Pilot Certificate and identification:", "o": ["Upon request", "Within 24 hours", "Only after an accident"], "k": "Upon request", "e": "Part 107 requires the certificate holder to make the certificate and ID available for inspection upon request by the FAA, NTSB, TSA, or law enforcement.", "img": null, "area": "regs"}, {"id": 173, "c": "Regulations", "a": "UA.I.B.K22", "q": "Before each flight, the remote PIC must assess the operating environment for:", "o": ["Local weather, airspace, people, property, and hazards", "Only battery percentage", "Only wind speed"], "k": "Local weather, airspace, people, property, and hazards", "e": "The preflight assessment includes weather, airspace, flight restrictions, people/property on the ground, and other hazards.", "img": null, "area": "regs"}, {"id": 174, "c": "Regulations", "a": "UA.I.B.K14", "q": "A small UA accident must be reported to the FAA within 10 days if it causes serious injury, loss of consciousness, or property damage (other than the UA) of at least:", "o": ["$500", "$1,000", "$5,000"], "k": "$500", "e": "Under 14 CFR 107.9, reportable accidents include serious injury/loss of consciousness or damage to property other than the sUAS exceeding $500, excluding labor to repair.", "img": null, "area": "regs"}, {"id": 175, "c": "Regulations", "a": "UA.I.B.K16", "q": "If a manned aircraft approaches your sUAS, who has the right-of-way?", "o": ["The manned aircraft", "The sUAS if below 400 ft", "Whichever aircraft is closer to the landing area"], "k": "The manned aircraft", "e": "The sUAS must yield the right-of-way to all aircraft, airborne vehicles, and launch/reentry vehicles.", "img": null, "area": "regs"}, {"id": 176, "c": "Weather", "a": "UA.III.B.K1", "q": "What generally happens to air pressure as altitude increases?", "o": ["It decreases", "It increases", "It stays constant"], "k": "It decreases", "e": "Atmospheric pressure decreases with altitude because there is less air above you exerting weight.", "img": null, "area": "wx"}, {"id": 177, "c": "Weather", "a": "UA.III.B.K1", "q": "A temperature/dew point spread of 2°C and decreasing indicates:", "o": ["Fog or low clouds may form", "Thunderstorms are impossible", "Density altitude will decrease sharply"], "k": "Fog or low clouds may form", "e": "When temperature approaches the dew point, the air is nearing saturation and fog/low clouds become more likely.", "img": null, "area": "wx"}, {"id": 178, "c": "Weather", "a": "UA.III.B.K1", "q": "Which condition is most likely with an unstable air mass?", "o": ["Turbulence and showery precipitation", "Smooth air and widespread haze", "Steady precipitation with poor visibility"], "k": "Turbulence and showery precipitation", "e": "Unstable air supports vertical motion, resulting in turbulence, cumuliform clouds, showers, and generally better visibility between showers.", "img": null, "area": "wx"}, {"id": 179, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, the code 'BKN020' means:", "o": ["Broken clouds at 2,000 ft AGL", "Broken clouds at 20,000 ft AGL", "Visibility 2.0 statute miles"], "k": "Broken clouds at 2,000 ft AGL", "e": "Cloud-base heights in METARs are reported in hundreds of feet AGL. 020 = 2,000 feet.", "img": null, "area": "wx"}, {"id": 180, "c": "Weather", "a": "UA.III.B.K1", "q": "When flying near buildings in strong wind, a remote pilot should expect:", "o": ["Turbulence and unpredictable eddies", "Perfectly smooth airflow", "Wind to stop completely behind the building"], "k": "Turbulence and unpredictable eddies", "e": "Structures disturb airflow and can create mechanical turbulence, rotors, and gusty eddies on the downwind side.", "img": null, "area": "wx"}, {"id": 181, "c": "Operations", "a": "UA.V.A.K2", "q": "A pilot who thinks 'I can handle it — I can do anything' is displaying which hazardous attitude?", "o": ["Macho", "Resignation", "Anti-authority"], "k": "Macho", "e": "The Macho hazardous attitude is characterized by risk-taking to prove ability. Its antidote is 'Taking chances is foolish.'", "img": null, "area": "ops"}, {"id": 182, "c": "Operations", "a": "UA.V.A.K2", "q": "In the DECIDE model, the first step is:", "o": ["Detect the fact that a change has occurred", "Do the necessary action", "Evaluate the outcome"], "k": "Detect the fact that a change has occurred", "e": "DECIDE stands for Detect, Estimate, Choose, Identify, Do, Evaluate.", "img": null, "area": "ops"}, {"id": 183, "c": "Operations", "a": "UA.V.A.K3", "q": "Good Crew Resource Management (CRM) includes:", "o": ["Clear communication and defined crew roles", "The PIC making every decision silently", "Allowing the VO to fly whenever desired"], "k": "Clear communication and defined crew roles", "e": "CRM uses communication, teamwork, workload management, and all available resources to improve safety.", "img": null, "area": "ops"}, {"id": 184, "c": "Operations", "a": "UA.V.A.K2", "q": "A remote pilot who has a cold and is taking medication should use which checklist before deciding to fly?", "o": ["IMSAFE", "PAVE", "DECIDE"], "k": "IMSAFE", "e": "IMSAFE checks Illness, Medication, Stress, Alcohol, Fatigue, and Emotion/Eating before flight.", "img": null, "area": "ops"}, {"id": 185, "c": "Operations", "a": "UA.V.A.K2", "q": "Continuing a flight because a client is waiting, despite worsening weather, is an example of:", "o": ["External pressure", "Invulnerability", "Anti-authority"], "k": "External pressure", "e": "External pressures such as schedules, customers, or the desire to complete a mission can push pilots toward unsafe decisions.", "img": null, "area": "ops"}, {"id": 186, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "You add a heavy payload below the drone. What is the most likely effect?", "o": ["Reduced flight time and changed handling", "Longer flight time", "No effect if the drone takes off"], "k": "Reduced flight time and changed handling", "e": "Additional weight increases power demand, reduces endurance, and can change center of gravity and control response.", "img": null, "area": "perf"}, {"id": 187, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Density altitude will be highest on a:", "o": ["Hot day at a high-elevation airport", "Cold day at sea level", "Cold day with high pressure"], "k": "Hot day at a high-elevation airport", "e": "High temperature and high elevation both increase density altitude and reduce aircraft performance.", "img": null, "area": "perf"}, {"id": 188, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Why is operating above the manufacturer's maximum takeoff weight unsafe?", "o": ["The aircraft may not have adequate thrust or control authority", "Remote ID stops working", "The GPS automatically disables"], "k": "The aircraft may not have adequate thrust or control authority", "e": "Excessive weight can reduce climb ability, maneuverability, stability, endurance, and motor/battery margins.", "img": null, "area": "perf"}, {"id": 189, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "If the center of gravity is outside the manufacturer's limits, the remote PIC should:", "o": ["Reconfigure the load before flight", "Fly slowly to compensate", "Increase altitude quickly"], "k": "Reconfigure the load before flight", "e": "An out-of-limit CG can make the aircraft unstable or uncontrollable. Correct the loading before takeoff.", "img": null, "area": "perf"}, {"id": 190, "c": "Loading & Performance", "a": "UA.IV.A.K2", "q": "Why does a strong headwind usually reduce a multirotor's usable flight time?", "o": ["The motors require more power to maintain groundspeed/position", "The battery becomes heavier", "The GPS uses more electricity than the motors"], "k": "The motors require more power to maintain groundspeed/position", "e": "Fighting wind increases thrust and current draw, reducing battery endurance.", "img": null, "area": "perf"}, {"id": 191, "c": "Airspace", "a": "UA.II.A.K1", "q": "You plan to fly in Class D airspace around an operating control tower. Before flight you generally need:", "o": ["ATC authorization", "Only the airport manager's permission", "No authorization below 400 ft"], "k": "ATC authorization", "e": "Part 107 operations in Class B, C, D, and surface Class E airspace require prior ATC authorization.", "img": null, "area": "air"}, {"id": 192, "c": "Airspace", "a": "UA.II.A.K3", "q": "A Temporary Flight Restriction (TFR) can be established for:", "o": ["Disasters, VIP movement, or major events", "Only military training", "Only airports without control towers"], "k": "Disasters, VIP movement, or major events", "e": "TFRs may protect disaster areas, VIP movements, space operations, major sporting events, and other temporary hazards/security needs.", "img": null, "area": "air"}, {"id": 193, "c": "Airspace", "a": "UA.II.A.K3", "q": "Before operating near a Military Operations Area (MOA), a remote pilot should:", "o": ["Check whether military activity is occurring and exercise caution", "Assume the MOA is always prohibited", "Ignore it because drones fly below 400 ft"], "k": "Check whether military activity is occurring and exercise caution", "e": "MOAs are not automatically prohibited to VFR operations, but military aircraft may maneuver at high speeds and low altitudes.", "img": null, "area": "air"}, {"id": 194, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class G airspace is:", "o": ["Uncontrolled airspace", "Always prohibited to drones", "Controlled airspace requiring LAANC everywhere"], "k": "Uncontrolled airspace", "e": "Class G is uncontrolled airspace. Other restrictions such as TFRs can still apply.", "img": null, "area": "air"}, {"id": 195, "c": "Airspace", "a": "UA.II.A.K1", "q": "A dashed magenta line surrounding an airport on a sectional chart indicates:", "o": ["Class E airspace beginning at the surface", "Class D airspace", "Class B airspace"], "k": "Class E airspace beginning at the surface", "e": "Dashed magenta boundaries depict Class E surface areas.", "img": null, "area": "air"}, {"id": 196, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "During preflight you find a small crack in a propeller. You should:", "o": ["Replace the propeller before flight", "Fly at reduced speed", "Apply tape and continue"], "k": "Replace the propeller before flight", "e": "Propellers experience high rotational loads. Even small cracks can propagate and cause failure in flight.", "img": null, "area": "ops"}, {"id": 197, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "After installing new firmware, the best practice is to:", "o": ["Conduct a controlled test flight before a critical mission", "Immediately use the aircraft on a paid mission", "Disable all warnings"], "k": "Conduct a controlled test flight before a critical mission", "e": "Updates can alter flight characteristics or settings. Verify proper operation in a safe environment first.", "img": null, "area": "ops"}, {"id": 198, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "A battery that is swollen should be:", "o": ["Removed from service", "Fully charged to rebalance it", "Used only for short flights"], "k": "Removed from service", "e": "Swelling indicates battery damage and increased fire/failure risk.", "img": null, "area": "ops"}, {"id": 199, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "If the control link is unreliable during a preflight check, the remote PIC should:", "o": ["Resolve the issue before takeoff", "Launch and remain close", "Increase altitude for better signal"], "k": "Resolve the issue before takeoff", "e": "The Remote PIC must determine the aircraft is in a condition for safe operation before flight.", "img": null, "area": "ops"}, {"id": 200, "c": "Maintenance", "a": "UA.VI.A.K1", "q": "Which is a good reason to keep voluntary maintenance records for a Part 107 drone?", "o": ["To track component history and recurring problems", "Because every drone must have an FAA airframe logbook", "To replace the preflight inspection"], "k": "To track component history and recurring problems", "e": "Maintenance logs help identify trends, document repairs, and support consistent inspections even when a formal aircraft logbook is not required.", "img": null, "area": "ops"}, {"id": 201, "c": "Airport Ops", "a": "UA.V.B.K1", "q": "At a non-towered airport, monitoring the CTAF can help a remote pilot:", "o": ["Maintain awareness of nearby manned aircraft", "Obtain automatic authorization to enter controlled airspace", "Control other aircraft"], "k": "Maintain awareness of nearby manned aircraft", "e": "CTAF monitoring can improve situational awareness of aircraft positions and intentions near non-towered airports.", "img": null, "area": "ops"}, {"id": 202, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "Runway 27 is aligned approximately:", "o": ["270° magnetic", "027° magnetic", "090° magnetic"], "k": "270° magnetic", "e": "Runway numbers correspond to magnetic heading rounded to the nearest 10 degrees and divided by 10.", "img": null, "area": "ops"}, {"id": 203, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "Yellow pavement markings are primarily associated with:", "o": ["Taxiways", "Runways", "Helipads only"], "k": "Taxiways", "e": "Runway markings are generally white, while taxiway centerlines and edge markings are yellow.", "img": null, "area": "ops"}, {"id": 204, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "A large yellow X on a runway indicates:", "o": ["The runway is closed", "The runway is restricted to helicopters", "The runway has a displaced threshold"], "k": "The runway is closed", "e": "An X marks a runway or taxiway as closed to aircraft operations.", "img": null, "area": "ops"}, {"id": 205, "c": "Airport Ops", "a": "UA.V.C.K1", "q": "When scanning for manned aircraft, the best visual technique is to:", "o": ["Use short, regularly spaced eye movements and focus briefly on each area", "Continuously sweep without stopping", "Stare at the horizon"], "k": "Use short, regularly spaced eye movements and focus briefly on each area", "e": "Traffic scanning is more effective when the eyes pause briefly in small sectors rather than continuously sweeping.", "img": null, "area": "ops"}, {"id": 211, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a solid blue line represent?", "o": ["Class B Airspace", "Class C Airspace", "Class D Airspace"], "k": "Class B Airspace", "e": "According to the Sectional Chart Legend, Class B airspace boundaries are shown with solid blue lines.", "img": "images/legend1.jpg", "area": "air"}, {"id": 212, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a solid magenta line represent?", "o": ["Class C Airspace", "Class B Airspace", "Class E Surface Airspace"], "k": "Class C Airspace", "e": "Class C airspace boundaries are shown with solid magenta lines.", "img": "images/legend1.jpg", "area": "air"}, {"id": 213, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a dashed blue line represent?", "o": ["Class D Airspace", "Class B Airspace", "Class E Airspace beginning at 700 ft AGL"], "k": "Class D Airspace", "e": "Class D airspace boundaries are depicted with dashed blue lines.", "img": "images/legend1.jpg", "area": "air"}, {"id": 214, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a dashed magenta line represent?", "o": ["Class E Airspace beginning at the surface", "Class D Airspace", "Class C Airspace"], "k": "Class E Airspace beginning at the surface", "e": "A dashed magenta line indicates Class E airspace extending upward from the surface.", "img": "images/legend1.jpg", "area": "air"}, {"id": 215, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A blue vignette (shaded blue border) indicates Class E airspace begins at:", "o": ["1200 ft AGL", "700 ft AGL", "The surface"], "k": "1200 ft AGL", "e": "A shaded blue vignette indicates Class E airspace beginning at 1,200 feet AGL.", "img": "images/legend1.jpg", "area": "air"}, {"id": 216, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A magenta vignette (shaded magenta border) indicates Class E airspace begins at:", "o": ["700 ft AGL", "1200 ft AGL", "The surface"], "k": "700 ft AGL", "e": "A shaded magenta vignette indicates Class E airspace beginning at 700 feet AGL.", "img": "images/legend1.jpg", "area": "air"}, {"id": 217, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a solid magenta line with a shaded side and altitude numbers indicate?", "o": ["Class C Airspace", "Special Use Airspace", "Military Training Route"], "k": "Class C Airspace", "e": "The solid magenta boundaries and altitude figures identify Class C airspace shelves and surface areas.", "img": "images/legend1.jpg", "area": "air"}, {"id": 218, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) The number shown over a Class B or C sector, such as '100/30', indicates:", "o": ["Ceiling over floor in hundreds of feet MSL", "Frequency and channel", "Runway length and width"], "k": "Ceiling over floor in hundreds of feet MSL", "e": "Airspace altitude numbers are shown as ceiling over floor, in hundreds of feet MSL. For example, 100/30 means 10,000 ft MSL over 3,000 ft MSL.", "img": "images/legend1.jpg", "area": "air"}, {"id": 219, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'SFC' mean when shown as the lower limit of controlled airspace?", "o": ["Surface", "Special Flight Corridor", "Standard Flight Clearance"], "k": "Surface", "e": "SFC means the controlled airspace begins at the surface.", "img": "images/legend1.jpg", "area": "air"}, {"id": 220, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'P-xx' identify?", "o": ["Prohibited Area", "Parachute Area", "Public Airport"], "k": "Prohibited Area", "e": "P followed by a number identifies a Prohibited Area where aircraft operations are generally not allowed.", "img": "images/legend1.jpg", "area": "air"}, {"id": 221, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'R-xxxx' identify?", "o": ["Restricted Area", "Radar Route", "Remote ID Zone"], "k": "Restricted Area", "e": "R followed by numbers identifies a Restricted Area containing unusual, often invisible hazards such as artillery or missile activity.", "img": "images/legend1.jpg", "area": "air"}, {"id": 222, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'W-xxx' identify?", "o": ["Warning Area", "Weather Area", "Wildlife Area"], "k": "Warning Area", "e": "Warning Areas are similar to Restricted Areas but are located over international waters.", "img": "images/legend1.jpg", "area": "air"}, {"id": 223, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'MOA' mean?", "o": ["Military Operations Area", "Mandatory Operations Area", "Meteorological Observation Area"], "k": "Military Operations Area", "e": "MOAs separate certain military training activities from IFR traffic and alert VFR pilots to military operations.", "img": "images/legend1.jpg", "area": "air"}, {"id": 224, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'A-xxx' identify?", "o": ["Alert Area", "Airport Area", "Approach Area"], "k": "Alert Area", "e": "Alert Areas have a high volume of pilot training or unusual aerial activity.", "img": "images/legend1.jpg", "area": "air"}, {"id": 225, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a heavy black line with hash marks labeled 'ADIZ' indicate?", "o": ["Air Defense Identification Zone", "Airport Development Information Zone", "Automated Drone Identification Zone"], "k": "Air Defense Identification Zone", "e": "The ADIZ is an Air Defense Identification Zone requiring special procedures for aircraft crossing it.", "img": "images/legend1.jpg", "area": "air"}, {"id": 226, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A blue segmented circle around an airport represents:", "o": ["Class D Airspace", "Class B Airspace", "Class E Airspace"], "k": "Class D Airspace", "e": "Dashed blue circles depict Class D airspace surrounding airports with operating control towers.", "img": "images/legend1.jpg", "area": "air"}, {"id": 227, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A magenta airport symbol means:", "o": ["Non-towered airport", "Tower-controlled airport", "Military airport"], "k": "Non-towered airport", "e": "Magenta airport symbols represent airports without an operating control tower.", "img": "images/legend1.jpg", "area": "air"}, {"id": 228, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A blue airport symbol means:", "o": ["Airport with an operating control tower", "Private airport", "Heliport"], "k": "Airport with an operating control tower", "e": "Blue airport symbols indicate airports with an operating control tower.", "img": "images/legend1.jpg", "area": "air"}, {"id": 229, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A small flag symbol indicates:", "o": ["VFR checkpoint", "Wind direction", "Temporary Flight Restriction"], "k": "VFR checkpoint", "e": "Flag symbols mark VFR checkpoints used by pilots for position reporting and navigation.", "img": "images/legend1.jpg", "area": "air"}, {"id": 230, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A parachute symbol indicates:", "o": ["Parachute Jumping Area", "Military Operations Area", "Restricted Area"], "k": "Parachute Jumping Area", "e": "The parachute symbol identifies locations where frequent parachute jumping occurs.", "img": "images/legend1.jpg", "area": "air"}, {"id": 231, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A glider symbol near an airport indicates:", "o": ["Glider activity", "Military training", "Airport closed"], "k": "Glider activity", "e": "A glider icon alerts pilots to glider operations in the area.", "img": "images/legend1.jpg", "area": "air"}, {"id": 232, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does a star above an airport symbol indicate?", "o": ["Rotating beacon operates sunset to sunrise", "Airport open 24 hours", "Fuel available"], "k": "Rotating beacon operates sunset to sunrise", "e": "A star above the airport symbol indicates that a rotating airport beacon operates from sunset to sunrise.", "img": "images/legend1.jpg", "area": "air"}, {"id": 233, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does '(Pvt)' following an airport name mean?", "o": ["Private-use airport", "Public-use airport", "Provisional airport"], "k": "Private-use airport", "e": "(Pvt) identifies an airport that is private-use and not open to the general public.", "img": "images/legend1.jpg", "area": "air"}, {"id": 234, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'UC' associated with an airport or runway mean?", "o": ["Under Construction", "Uncontrolled", "Unicom Available"], "k": "Under Construction", "e": "UC indicates the airport or runway is under construction.", "img": "images/legend1.jpg", "area": "air"}, {"id": 235, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does 'CTAF' stand for?", "o": ["Common Traffic Advisory Frequency", "Controlled Traffic Authorization Frequency", "Common Terminal Airport Frequency"], "k": "Common Traffic Advisory Frequency", "e": "CTAF is the frequency pilots use to self-announce their position and intentions at non-towered airports.", "img": "images/legend1.jpg", "area": "air"}, {"id": 236, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A runway length shown as '52' means the runway is approximately:", "o": ["5,200 feet long", "520 feet long", "52,000 feet long"], "k": "5,200 feet long", "e": "Runway lengths on sectional charts are shown in hundreds of feet. '52' indicates approximately 5,200 feet.", "img": "images/legend1.jpg", "area": "air"}, {"id": 237, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) The letter 'L' following a runway length indicates:", "o": ["Runway lighting is available", "Left traffic pattern", "Limited-use runway"], "k": "Runway lighting is available", "e": "The letter L indicates runway lighting. Specific lighting limitations may be found in the Chart Supplement.", "img": "images/legend1.jpg", "area": "air"}, {"id": 238, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) An obstruction shown as '1548 (355)' means:", "o": ["1548 ft MSL and 355 ft AGL", "1548 ft AGL and 355 ft MSL", "1548 ft from airport and 355 ft tall"], "k": "1548 ft MSL and 355 ft AGL", "e": "The top number is the elevation of the top of the obstruction in MSL; the number in parentheses is the height above ground level.", "img": "images/legend1.jpg", "area": "air"}, {"id": 239, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) What does the Maximum Elevation Figure (MEF) represent?", "o": ["Highest terrain or obstruction within a chart quadrangle, rounded up with a safety margin", "Maximum legal drone altitude", "Maximum airport field elevation"], "k": "Highest terrain or obstruction within a chart quadrangle, rounded up with a safety margin", "e": "The MEF provides the approximate highest elevation within each quadrangle, including terrain/obstructions and a margin.", "img": "images/legend1.jpg", "area": "air"}, {"id": 240, "c": "Charts", "a": "UA.II.A.K2", "q": "(Refer to the Sectional Chart Legend) A large blue number such as '34' printed in a quadrangle is most likely:", "o": ["Maximum Elevation Figure — 3,400 ft MSL", "Class B ceiling — 34,000 ft", "Airport frequency 134.0"], "k": "Maximum Elevation Figure — 3,400 ft MSL", "e": "MEFs are shown in hundreds of feet MSL. A value of 34 indicates approximately 3,400 feet MSL.", "img": "images/legend1.jpg", "area": "air"}, {"id": 1007, "c": "Regulations", "a": "UA.I.B.K21", "q": "How close may a small UAS fly vertically to a structure and exceed 400 feet AGL?", "o": ["Within 400 feet of the structure", "Within 1,000 feet of the structure", "Only directly over the structure"], "k": "Within 400 feet of the structure", "e": "Part 107 allows flight above 400 feet AGL when the aircraft remains within 400 feet of a structure and no more than 400 feet above its uppermost limit.", "img": null, "area": "regs"}, {"id": 2001, "c": "Regulations", "a": "UA.I.C.K1", "q": "What is the minimum age to be eligible for a Remote Pilot Certificate?", "o": ["16 years old", "14 years old", "18 years old"], "k": "16 years old", "e": "14 CFR 107.61 requires an applicant to be at least 16 years old.", "img": null, "area": "regs"}, {"id": 2002, "c": "Regulations", "a": "UA.I.C.K1", "q": "Which is an eligibility requirement for a Remote Pilot Certificate?", "o": ["Be able to read, speak, write, and understand English", "Hold a current FAA medical certificate", "Own a registered small UA"], "k": "Be able to read, speak, write, and understand English", "e": "Section 107.61 requires English proficiency (unless the FAA grants an exception for a medical reason). No medical certificate is required.", "img": null, "area": "regs"}, {"id": 2003, "c": "Regulations", "a": "UA.I.C.K1", "q": "Does a remote pilot need an FAA medical certificate to operate under Part 107?", "o": ["No, but they must not have a known condition that would interfere with safe operation", "Yes, at least a third-class medical", "Yes, a basic BasicMed certificate"], "k": "No, but they must not have a known condition that would interfere with safe operation", "e": "No medical certificate is required, but 107.17 prohibits operating with a known physical or mental condition that interferes with safe operation.", "img": null, "area": "regs"}, {"id": 2004, "c": "Regulations", "a": "UA.I.C.K2", "q": "How many questions are on the initial Unmanned Aircraft General (UAG) knowledge test, and what score is needed to pass?", "o": ["60 questions, 70 percent", "50 questions, 80 percent", "100 questions, 70 percent"], "k": "60 questions, 70 percent", "e": "The initial UAG test has 60 multiple-choice questions and a minimum passing score of 70 percent.", "img": null, "area": "regs"}, {"id": 2005, "c": "Regulations", "a": "UA.I.C.K2", "q": "After passing the initial knowledge test, where does a person apply for the Remote Pilot Certificate?", "o": ["IACRA (Integrated Airman Certification and Rating Application)", "FAADroneZone", "LAANC"], "k": "IACRA (Integrated Airman Certification and Rating Application)", "e": "Applicants complete FAA Form 8710-13 through IACRA after passing the test.", "img": null, "area": "regs"}, {"id": 2006, "c": "Regulations", "a": "UA.I.C.K2", "q": "What does the applicant receive after the TSA security check is completed through IACRA?", "o": ["A temporary certificate they can print and use until the permanent card arrives", "A permanent certificate the same day", "Nothing until the plastic card arrives by mail"], "k": "A temporary certificate they can print and use until the permanent card arrives", "e": "Once TSA vetting is complete, IACRA issues a temporary remote pilot certificate, valid for 120 days, that can be printed.", "img": null, "area": "regs"}, {"id": 2007, "c": "Regulations", "a": "UA.I.C.K2", "q": "A temporary remote pilot certificate is valid for:", "o": ["120 days", "60 days", "24 calendar months"], "k": "120 days", "e": "The temporary certificate is valid for 120 days while the permanent certificate is processed.", "img": null, "area": "regs"}, {"id": 2008, "c": "Regulations", "a": "UA.I.C.K3", "q": "To keep exercising the privileges of a Remote Pilot Certificate, a remote pilot must complete recurrent training:", "o": ["Within the previous 24 calendar months", "Within the previous 12 calendar months", "Every 5 years"], "k": "Within the previous 24 calendar months", "e": "Section 107.65 requires passing the initial test or completing recurrent training within the previous 24 calendar months.", "img": null, "area": "regs"}, {"id": 2009, "c": "Regulations", "a": "UA.I.C.K3", "q": "How is recurrent knowledge currency for a remote pilot normally completed today?", "o": ["A free online training course through FAASTeam", "A proctored test at an FAA testing center only", "A flight check with an FAA inspector"], "k": "A free online training course through FAASTeam", "e": "Remote pilots can complete free online recurrent training (ALC-677) through the FAASTeam website.", "img": null, "area": "regs"}, {"id": 2010, "c": "Regulations", "a": "UA.I.C.K3", "q": "A remote pilot passed the initial test on March 10, 2025. Through what date are they current?", "o": ["March 31, 2027", "March 10, 2027", "March 31, 2026"], "k": "March 31, 2027", "e": "24 calendar months ends on the last day of the month, so currency runs through March 31, 2027.", "img": null, "area": "regs"}, {"id": 2011, "c": "Regulations", "a": "UA.I.B.K1", "q": "Under Part 107, which small unmanned aircraft must be registered?", "o": ["All small UA operated under Part 107, regardless of weight", "Only small UA weighing more than 0.55 pounds", "Only small UA weighing more than 2 pounds"], "k": "All small UA operated under Part 107, regardless of weight", "e": "Unlike recreational flyers, Part 107 operators must register every small UA, even those 0.55 pounds or less.", "img": null, "area": "regs"}, {"id": 2012, "c": "Regulations", "a": "UA.I.B.K1", "q": "How long is an FAA small UA registration valid?", "o": ["3 years", "1 year", "5 years"], "k": "3 years", "e": "Registration under Part 48 must be renewed every 3 years.", "img": null, "area": "regs"}, {"id": 2013, "c": "Regulations", "a": "UA.I.B.K1", "q": "Where must the FAA registration number be displayed on a small UA?", "o": ["On an external surface of the aircraft", "Inside the battery compartment only", "On the controller"], "k": "On an external surface of the aircraft", "e": "The registration number must be legible and visible on an external surface of the aircraft.", "img": null, "area": "regs"}, {"id": 2014, "c": "Regulations", "a": "UA.I.B.K2", "q": "Which documents must a remote PIC have in their physical or electronic possession during operation?", "o": ["Remote Pilot Certificate and any applicable waiver, plus photo ID", "Pilot logbook and medical certificate", "Aircraft maintenance records"], "k": "Remote Pilot Certificate and any applicable waiver, plus photo ID", "e": "The remote PIC must carry the certificate and be ready to present it, along with any waiver or authorization, on request.", "img": null, "area": "regs"}, {"id": 2015, "c": "Regulations", "a": "UA.I.B.K2", "q": "Who may request to see a remote pilot's certificate and the small UAS?", "o": ["The FAA, NTSB, TSA, or any federal, state, or local law enforcement officer", "Only the FAA", "Any member of the public"], "k": "The FAA, NTSB, TSA, or any federal, state, or local law enforcement officer", "e": "Section 107.7 lists the FAA, NTSB, TSA, and federal, state, or local law enforcement.", "img": null, "area": "regs"}, {"id": 2016, "c": "Regulations", "a": "UA.I.B.K3", "q": "Which events require an accident report to the FAA within 10 calendar days?", "o": ["Serious injury, loss of consciousness, or property damage over $500 (not counting the small UA)", "Any landing outside the planned area", "Any damage to the small UA"], "k": "Serious injury, loss of consciousness, or property damage over $500 (not counting the small UA)", "e": "Section 107.9 requires a report within 10 days for serious injury, loss of consciousness, or damage to other property over $500 to repair or replace.", "img": null, "area": "regs"}, {"id": 2017, "c": "Regulations", "a": "UA.I.B.K3", "q": "Your drone lands on a parked car, causing $700 in damage. The drone itself needs $900 in repairs. Must this be reported?", "o": ["Yes, because damage to the car exceeds $500", "No, the drone damage does not count", "Only if someone was injured"], "k": "Yes, because damage to the car exceeds $500", "e": "Damage to property other than the small UA over $500 must be reported within 10 days.", "img": null, "area": "regs"}, {"id": 2018, "c": "Regulations", "a": "UA.I.B.K3", "q": "An accident report to the FAA may be submitted:", "o": ["Through the FAADroneZone online", "Only by mail", "Only in person at a FSDO"], "k": "Through the FAADroneZone online", "e": "Reports can be filed online through FAADroneZone, or with the nearest FSDO.", "img": null, "area": "regs"}, {"id": 2019, "c": "Regulations", "a": "UA.I.B.K4", "q": "Who may deviate from Part 107 rules during an in-flight emergency?", "o": ["The remote pilot in command, to the extent needed to meet the emergency", "Only an FAA inspector", "No one may ever deviate"], "k": "The remote pilot in command, to the extent needed to meet the emergency", "e": "Section 107.21 allows the remote PIC to deviate from Part 107 to respond to an in-flight emergency.", "img": null, "area": "regs"}, {"id": 2020, "c": "Regulations", "a": "UA.I.B.K4", "q": "If a remote PIC deviates from a rule during an emergency, they must:", "o": ["Send a written report to the FAA upon request", "Stop flying for 30 days", "File a NOTAM"], "k": "Send a written report to the FAA upon request", "e": "A remote PIC who deviates in an emergency must report it to the FAA if requested.", "img": null, "area": "regs"}, {"id": 2021, "c": "Regulations", "a": "UA.I.B.K5", "q": "Which is true about operating a small UA from a moving vehicle?", "o": ["It is allowed only over sparsely populated areas", "It is allowed anywhere if a VO is used", "It is allowed from a moving aircraft over open water"], "k": "It is allowed only over sparsely populated areas", "e": "Section 107.25 allows it only over a sparsely populated area, and never from a moving aircraft.", "img": null, "area": "regs"}, {"id": 2022, "c": "Regulations", "a": "UA.I.B.K6", "q": "Dropping an object from a small UA is:", "o": ["Allowed if it does not create undue hazard to persons or property", "Never allowed", "Allowed only with a waiver"], "k": "Allowed if it does not create undue hazard to persons or property", "e": "Section 107.23 permits dropping objects as long as it does not create an undue hazard.", "img": null, "area": "regs"}, {"id": 2023, "c": "Regulations", "a": "UA.I.B.K8", "q": "A remote pilot may not act as a crewmember if they have consumed alcohol within the previous:", "o": ["8 hours", "4 hours", "12 hours"], "k": "8 hours", "e": "Section 91.17 (referenced by 107.27) prohibits acting as a crewmember within 8 hours after drinking.", "img": null, "area": "regs"}, {"id": 2024, "c": "Regulations", "a": "UA.I.B.K8", "q": "A remote pilot may refuse an alcohol test requested by law enforcement without consequence.", "o": ["False. Refusing may result in denial, suspension, or revocation of the certificate", "True. Testing is voluntary", "True, unless an accident occurred"], "k": "False. Refusing may result in denial, suspension, or revocation of the certificate", "e": "Refusing a test or to furnish results under 91.17 can lead to denial, suspension, or revocation.", "img": null, "area": "regs"}, {"id": 2025, "c": "Regulations", "a": "UA.I.B.K9", "q": "Which rule applies to flying during civil twilight?", "o": ["The small UA must have anti-collision lighting visible for at least 3 statute miles", "No lighting is required", "Night operations require a waiver"], "k": "The small UA must have anti-collision lighting visible for at least 3 statute miles", "e": "Civil twilight and night operations require anti-collision lights visible for 3 SM with a sufficient flash rate.", "img": null, "area": "regs"}, {"id": 2026, "c": "Regulations", "a": "UA.I.B.K9", "q": "Civil twilight is the period:", "o": ["30 minutes before official sunrise and 30 minutes after official sunset (in the lower 48)", "1 hour before sunrise and 1 hour after sunset", "From sunset to sunrise"], "k": "30 minutes before official sunrise and 30 minutes after official sunset (in the lower 48)", "e": "In the contiguous U.S., civil twilight is roughly 30 minutes before sunrise and 30 minutes after sunset (Alaska differs).", "img": null, "area": "regs"}, {"id": 2027, "c": "Regulations", "a": "UA.I.B.K9", "q": "Before flying at night under Part 107, a remote pilot who passed the test before April 2021 must:", "o": ["Complete the updated initial or recurrent training that covers night operations", "Obtain a night waiver", "Hold a private pilot certificate"], "k": "Complete the updated initial or recurrent training that covers night operations", "e": "Pilots certified before April 6, 2021 must complete updated training covering night operations.", "img": null, "area": "regs"}, {"id": 2028, "c": "Regulations", "a": "UA.I.B.K25", "q": "When may a remote pilot reduce the intensity of the anti-collision lights during a night flight?", "o": ["When it is in the interest of safety", "Whenever the battery is low", "Never"], "k": "When it is in the interest of safety", "e": "Section 107.29 allows reducing light intensity if it is in the interest of safety.", "img": null, "area": "regs"}, {"id": 2029, "c": "Regulations", "a": "UA.I.B.K10", "q": "What does visual line of sight (VLOS) require?", "o": ["Seeing the small UA with vision unaided by any device other than corrective lenses", "Seeing the drone on the FPV screen", "Seeing the drone through binoculars"], "k": "Seeing the small UA with vision unaided by any device other than corrective lenses", "e": "Section 107.31 requires unaided vision (glasses or contacts are allowed).", "img": null, "area": "regs"}, {"id": 2030, "c": "Regulations", "a": "UA.I.B.K10", "q": "Why must the small UA stay within VLOS?", "o": ["To know its location, determine its attitude, altitude, and direction, observe airspace for hazards, and ensure it does not endanger anyone", "Only so the control link stays strong", "Only to film properly"], "k": "To know its location, determine its attitude, altitude, and direction, observe airspace for hazards, and ensure it does not endanger anyone", "e": "Section 107.31 lists these reasons for maintaining visual line of sight.", "img": null, "area": "regs"}, {"id": 2031, "c": "Regulations", "a": "UA.I.B.K10", "q": "Can a remote pilot use first-person view (FPV) goggles under Part 107?", "o": ["Yes, if a visual observer maintains VLOS and they can talk directly", "No, FPV is never allowed", "Yes, with no observer needed"], "k": "Yes, if a visual observer maintains VLOS and they can talk directly", "e": "FPV is allowed when a VO maintains unaided VLOS and communicates with the pilot.", "img": null, "area": "regs"}, {"id": 2032, "c": "Regulations", "a": "UA.I.B.K11", "q": "A visual observer must:", "o": ["Be able to see the small UA and communicate effectively with the remote PIC", "Hold a Remote Pilot Certificate", "Be at least 18 years old"], "k": "Be able to see the small UA and communicate effectively with the remote PIC", "e": "The VO needs no certificate but must maintain VLOS and communicate with the remote PIC (107.33).", "img": null, "area": "regs"}, {"id": 2033, "c": "Regulations", "a": "UA.I.B.K12", "q": "How many small UA may one remote pilot operate at the same time under Part 107 without a waiver?", "o": ["One", "Two", "Five"], "k": "One", "e": "Section 107.35 limits a person to operating or acting as remote PIC of only one small UA at a time.", "img": null, "area": "regs"}, {"id": 2034, "c": "Regulations", "a": "UA.I.B.K13", "q": "What must a remote PIC do when approaching a manned aircraft?", "o": ["Yield the right of way and avoid passing over, under, or ahead of it unless well clear", "Climb above it", "Continue if the drone is lower"], "k": "Yield the right of way and avoid passing over, under, or ahead of it unless well clear", "e": "Section 107.37 requires yielding to all aircraft and staying well clear.", "img": null, "area": "regs"}, {"id": 2035, "c": "Regulations", "a": "UA.I.B.K15", "q": "Which statement about operating in Class G airspace is correct?", "o": ["No ATC authorization is required", "LAANC authorization is required", "A waiver is required"], "k": "No ATC authorization is required", "e": "Class G is uncontrolled airspace, so no ATC authorization is needed under 107.41.", "img": null, "area": "regs"}, {"id": 2036, "c": "Regulations", "a": "UA.I.B.K16", "q": "Under Part 107, flight is not allowed in prohibited or restricted areas unless:", "o": ["Permission is granted by the using or controlling agency", "The drone is below 400 feet", "It is a weekend"], "k": "Permission is granted by the using or controlling agency", "e": "Section 107.45 requires permission from the controlling agency.", "img": null, "area": "regs"}, {"id": 2037, "c": "Regulations", "a": "UA.I.B.K17", "q": "Before each flight, the remote PIC must:", "o": ["Assess the operating environment, brief participants, and ensure the control link works", "File a flight plan with ATC", "Call the nearest FSDO"], "k": "Assess the operating environment, brief participants, and ensure the control link works", "e": "Section 107.49 lists preflight familiarization, inspection, and crew briefing requirements.", "img": null, "area": "regs"}, {"id": 2038, "c": "Regulations", "a": "UA.I.B.K17", "q": "Which is part of the preflight assessment required by 107.49?", "o": ["Local weather, airspace restrictions, location of people and property, and ground hazards", "The color of the aircraft", "Fuel prices"], "k": "Local weather, airspace restrictions, location of people and property, and ground hazards", "e": "The remote PIC must assess these conditions before flight.", "img": null, "area": "regs"}, {"id": 2039, "c": "Regulations", "a": "UA.I.B.K19", "q": "Without a waiver, may a small UA fly over a moving vehicle?", "o": ["Only in limited cases, such as Category 1, 2, or 3 rules with transit only, or in a restricted access area", "Yes, at any time", "Never, under any circumstances"], "k": "Only in limited cases, such as Category 1, 2, or 3 rules with transit only, or in a restricted access area", "e": "The operations over people rule allows sustained flight over moving vehicles only in closed or restricted access sites; otherwise transit only.", "img": null, "area": "regs"}, {"id": 2040, "c": "Regulations", "a": "UA.I.B.K19", "q": "Category 4 operations over people require the small UA to have:", "o": ["An FAA airworthiness certificate", "A Declaration of Compliance only", "Weight under 0.55 pounds"], "k": "An FAA airworthiness certificate", "e": "Category 4 aircraft must hold an airworthiness certificate under Part 21.", "img": null, "area": "regs"}, {"id": 2041, "c": "Regulations", "a": "UA.I.B.K19", "q": "A Category 1 drone over people must weigh 0.55 pounds or less and:", "o": ["Have no exposed rotating parts that could lacerate skin", "Have a parachute", "Fly no higher than 50 feet"], "k": "Have no exposed rotating parts that could lacerate skin", "e": "Category 1 requires 0.55 pounds or less, including everything onboard, and no exposed rotating parts that would cause lacerations.", "img": null, "area": "regs"}, {"id": 2042, "c": "Regulations", "a": "UA.I.B.K19", "q": "Sustained flight over an open-air assembly of people is allowed when:", "o": ["The drone meets Category 1, 2, or 3 and complies with Remote ID", "The pilot holds a waiver only", "Never, under any rule"], "k": "The drone meets Category 1, 2, or 3 and complies with Remote ID", "e": "Operations over open-air assemblies require Remote ID compliance and a Category 1, 2, or 3 eligible drone.", "img": null, "area": "regs"}, {"id": 2043, "c": "Regulations", "a": "UA.I.B.K20", "q": "Who is responsible for determining the performance of a small unmanned aircraft?", "o": ["The remote pilot in command", "The manufacturer", "The FAA"], "k": "The remote pilot in command", "e": "Section 107.49 and 107.19 make the remote PIC responsible.", "img": null, "area": "regs"}, {"id": 2044, "c": "Regulations", "a": "UA.I.B.K21", "q": "When flying within 400 feet of a structure, a small UA may fly higher than 400 feet AGL as long as it stays:", "o": ["Within a 400-foot radius and no higher than 400 feet above the structure's top", "Within 1,000 feet of the structure", "Directly over the structure only"], "k": "Within a 400-foot radius and no higher than 400 feet above the structure's top", "e": "Section 107.51(b) allows this exception.", "img": null, "area": "regs"}, {"id": 2045, "c": "Regulations", "a": "UA.I.B.K21", "q": "A remote pilot inspects a 500-foot tower. What is the highest they may fly?", "o": ["900 feet AGL, within 400 feet of the tower", "500 feet AGL", "400 feet AGL"], "k": "900 feet AGL, within 400 feet of the tower", "e": "400 feet above the 500-foot structure is 900 feet AGL, staying within a 400-foot radius.", "img": null, "area": "regs"}, {"id": 2046, "c": "Regulations", "a": "UA.I.B.K21", "q": "Cloud clearance requirements under Part 107 are:", "o": ["500 feet below and 2,000 feet horizontally", "1,000 feet below and 1 mile horizontally", "Clear of clouds"], "k": "500 feet below and 2,000 feet horizontally", "e": "Section 107.51(d) requires 500 feet below and 2,000 feet horizontally from clouds.", "img": null, "area": "regs"}, {"id": 2047, "c": "Regulations", "a": "UA.I.B.K21", "q": "Minimum flight visibility as observed from the control station must be:", "o": ["3 statute miles", "1 statute mile", "5 statute miles"], "k": "3 statute miles", "e": "Section 107.51(c) requires 3 statute miles.", "img": null, "area": "regs"}, {"id": 2048, "c": "Regulations", "a": "UA.I.B.K22", "q": "Which operating rules may be waived under 107.205?", "o": ["Operations from a moving vehicle, night (lighting), VLOS, multiple UA, altitude, and others", "Carrying hazardous materials", "Operating while impaired"], "k": "Operations from a moving vehicle, night (lighting), VLOS, multiple UA, altitude, and others", "e": "Many rules can be waived, but carrying hazmat (107.36) and alcohol and drug rules cannot.", "img": null, "area": "regs"}, {"id": 2049, "c": "Regulations", "a": "UA.I.B.K22", "q": "A request for a Part 107 waiver is submitted through:", "o": ["FAADroneZone", "LAANC", "Flight Service by phone"], "k": "FAADroneZone", "e": "Waiver applications are submitted through the FAADroneZone portal.", "img": null, "area": "regs"}, {"id": 2050, "c": "Regulations", "a": "UA.I.B.K22", "q": "How far in advance should a waiver or airspace authorization request be submitted?", "o": ["At least 90 days before the operation", "24 hours before", "7 days before"], "k": "At least 90 days before the operation", "e": "The FAA recommends submitting at least 90 days in advance.", "img": null, "area": "regs"}, {"id": 2051, "c": "Regulations", "a": "UA.I.B.K7", "q": "Which rule cannot be waived?", "o": ["Carriage of hazardous materials", "Daylight operation", "Maximum altitude"], "k": "Carriage of hazardous materials", "e": "Section 107.36 (hazardous materials) is not listed in 107.205 and cannot be waived.", "img": null, "area": "regs"}, {"id": 2052, "c": "Regulations", "a": "UA.I.F.K1", "q": "Which three ways can a drone meet the Remote ID rule?", "o": ["Standard Remote ID, a Remote ID broadcast module, or flying in an FAA-recognized identification area (FRIA)", "ADS-B Out, transponder, or radio", "Registration sticker, light, or beacon"], "k": "Standard Remote ID, a Remote ID broadcast module, or flying in an FAA-recognized identification area (FRIA)", "e": "The Remote ID rule allows standard RID drones, broadcast modules, or FRIAs.", "img": null, "area": "regs"}, {"id": 2053, "c": "Regulations", "a": "UA.I.F.K1", "q": "A drone with a Remote ID broadcast module must be flown:", "o": ["Within visual line of sight", "Only above 200 feet", "Only at night"], "k": "Within visual line of sight", "e": "Broadcast-module operations must stay within VLOS of the operator.", "img": null, "area": "regs"}, {"id": 2054, "c": "Regulations", "a": "UA.I.F.K1", "q": "If standard Remote ID fails during flight, the remote PIC must:", "o": ["Land as soon as practicable", "Continue until the battery is low", "Climb to 400 feet"], "k": "Land as soon as practicable", "e": "Standard RID aircraft must land as soon as practicable if the broadcast fails.", "img": null, "area": "regs"}, {"id": 2055, "c": "Regulations", "a": "UA.I.F.K1", "q": "What information does standard Remote ID broadcast?", "o": ["Drone ID, location, altitude, velocity, control station location, emergency status, and time", "Pilot's name and address", "Only the registration number"], "k": "Drone ID, location, altitude, velocity, control station location, emergency status, and time", "e": "Standard RID broadcasts these message elements, not the pilot's personal information.", "img": null, "area": "regs"}, {"id": 2056, "c": "Regulations", "a": "UA.I.F.K1", "q": "Where must the serial number of a standard Remote ID drone or broadcast module be listed?", "o": ["On the FAA registration for that aircraft", "On the remote pilot certificate", "In the drone's logbook"], "k": "On the FAA registration for that aircraft", "e": "The serial number must be entered on the drone's FAA registration.", "img": null, "area": "regs"}, {"id": 2057, "c": "Regulations", "a": "UA.I.B.K18", "q": "Who must ensure the small UA is in a condition for safe operation before flight?", "o": ["The remote PIC", "The visual observer", "The owner"], "k": "The remote PIC", "e": "Section 107.15 makes the remote PIC responsible for checking the condition for safe operation.", "img": null, "area": "regs"}, {"id": 2058, "c": "Regulations", "a": "UA.I.B.K23", "q": "A person without a Remote Pilot Certificate may manipulate the controls if:", "o": ["They are directly supervised by a remote PIC who can immediately take over", "They have watched training videos", "They are over 18"], "k": "They are directly supervised by a remote PIC who can immediately take over", "e": "Section 107.12 allows this under direct supervision with immediate takeover capability.", "img": null, "area": "regs"}, {"id": 2059, "c": "Regulations", "a": "UA.I.B.K24", "q": "Part 107 does NOT apply to:", "o": ["Model aircraft flown under 49 U.S.C. 44809 (recreational), and certain government operations", "Commercial real estate photography", "Roof inspections for pay"], "k": "Model aircraft flown under 49 U.S.C. 44809 (recreational), and certain government operations", "e": "Recreational flying under 44809 and public aircraft operations are outside Part 107.", "img": null, "area": "regs"}, {"id": 2060, "c": "Regulations", "a": "UA.I.B.K24", "q": "A recreational flyer who wants to fly under the recreational exception must pass:", "o": ["The Recreational UAS Safety Test (TRUST)", "The UAG knowledge test", "A practical flight test"], "k": "The Recreational UAS Safety Test (TRUST)", "e": "Recreational flyers take TRUST; Part 107 pilots take the UAG test.", "img": null, "area": "regs"}, {"id": 2061, "c": "Regulations", "a": "UA.I.C.K2", "q": "A person whose certificate is suspended or revoked may:", "o": ["Not operate under Part 107 until it is reinstated", "Continue flying with supervision", "Keep flying for 30 days"], "k": "Not operate under Part 107 until it is reinstated", "e": "A suspended or revoked certificate removes the privilege to act as remote PIC.", "img": null, "area": "regs"}, {"id": 2062, "c": "Regulations", "a": "UA.I.C.K2", "q": "A conviction for a federal or state drug offense can result in:", "o": ["Denial of an application for up to 1 year after the conviction, or suspension or revocation", "Automatic lifetime ban", "No action"], "k": "Denial of an application for up to 1 year after the conviction, or suspension or revocation", "e": "Section 107.57 allows denial up to 1 year after the final conviction, or suspension or revocation.", "img": null, "area": "regs"}, {"id": 2063, "c": "Regulations", "a": "UA.I.C.K2", "q": "Within how many days of a change in permanent mailing address must a remote pilot notify the FAA?", "o": ["30 days", "10 days", "60 days"], "k": "30 days", "e": "Section 107.77 requires notice within 30 days to keep exercising certificate privileges.", "img": null, "area": "regs"}, {"id": 2064, "c": "Regulations", "a": "UA.I.B.K2", "q": "The FAA can request the remote PIC to make the small UAS available for inspection or testing. Who must comply?", "o": ["The owner or remote PIC", "Only the manufacturer", "No one, it is optional"], "k": "The owner or remote PIC", "e": "Section 107.7(b) requires making the sUAS and records available on request.", "img": null, "area": "regs"}, {"id": 2065, "c": "Regulations", "a": "UA.I.B.K5", "q": "Can a small UA be used to carry property for compensation across state lines?", "o": ["Not without additional FAA authority. Part 107 transport for compensation is limited to within a state", "Yes, always", "Only from a moving vehicle"], "k": "Not without additional FAA authority. Part 107 transport for compensation is limited to within a state", "e": "Part 107 property transport must stay within a state; interstate carriage needs other FAA approval.", "img": null, "area": "regs"}, {"id": 2066, "c": "Regulations", "a": "UA.I.B.K12", "q": "Which statement about a remote PIC and the person manipulating the controls is true?", "o": ["The remote PIC has final authority and responsibility for the operation", "The person manipulating the controls is always in charge", "Responsibility is shared equally"], "k": "The remote PIC has final authority and responsibility for the operation", "e": "Section 107.19 gives the remote PIC final authority.", "img": null, "area": "regs"}, {"id": 2067, "c": "Regulations", "a": "UA.I.B.K13", "q": "May a small UA interfere with airport operations and traffic patterns?", "o": ["No. The remote PIC must not interfere with operations at any airport, heliport, or seaplane base", "Yes, if below 400 feet", "Yes, at non-towered airports"], "k": "No. The remote PIC must not interfere with operations at any airport, heliport, or seaplane base", "e": "Section 107.43 prohibits interfering with airport operations.", "img": null, "area": "regs"}, {"id": 2068, "c": "Regulations", "a": "UA.I.B.K15", "q": "Operations in Class B, C, or D airspace, or within the lateral boundaries of the surface area of Class E for an airport, require:", "o": ["Prior authorization from ATC", "A NOTAM", "Only a call to the airport manager"], "k": "Prior authorization from ATC", "e": "Section 107.41 requires ATC authorization (such as through LAANC or DroneZone).", "img": null, "area": "regs"}, {"id": 2069, "c": "Regulations", "a": "UA.I.B.K16", "q": "Flight within a TFR is:", "o": ["Not allowed unless the operation is authorized under the TFR's terms", "Allowed below 400 feet", "Allowed if the drone weighs under 55 pounds"], "k": "Not allowed unless the operation is authorized under the TFR's terms", "e": "Section 107.47 and 99.7 require following TFR and special security instructions.", "img": null, "area": "regs"}, {"id": 2070, "c": "Regulations", "a": "UA.I.B.K16", "q": "Major sporting event stadium TFRs typically cover:", "o": ["3 nautical miles and 3,000 feet AGL, from 1 hour before to 1 hour after the event", "1 mile and 400 feet", "10 miles and 18,000 feet"], "k": "3 nautical miles and 3,000 feet AGL, from 1 hour before to 1 hour after the event", "e": "Stadium TFRs for qualifying events cover 3 NM and below 3,000 feet AGL.", "img": null, "area": "regs"}, {"id": 2071, "c": "Airspace", "a": "UA.II.A.K1", "q": "What is LAANC?", "o": ["Low Altitude Authorization and Notification Capability, which gives near real-time airspace authorizations", "A type of Remote ID module", "A military training route"], "k": "Low Altitude Authorization and Notification Capability, which gives near real-time airspace authorizations", "e": "LAANC lets pilots get automated authorization in controlled airspace below UAS Facility Map altitudes.", "img": null, "area": "air"}, {"id": 2072, "c": "Airspace", "a": "UA.II.A.K1", "q": "The altitudes shown on a UAS Facility Map are:", "o": ["The maximum altitudes ATC may approve without further safety review", "The minimum altitudes allowed", "Altitudes where drones are prohibited"], "k": "The maximum altitudes ATC may approve without further safety review", "e": "UASFM grid numbers show the maximum altitude (AGL) that can usually be approved through LAANC.", "img": null, "area": "air"}, {"id": 2073, "c": "Airspace", "a": "UA.II.A.K1", "q": "A UAS Facility Map grid shows 0 near the end of a runway. This means:", "o": ["Authorization at that location needs further coordination, not automatic LAANC approval", "Drones may fly at any altitude", "The grid is Class G"], "k": "Authorization at that location needs further coordination, not automatic LAANC approval", "e": "A 0 grid means LAANC cannot auto-approve; a further coordination request is needed.", "img": null, "area": "air"}, {"id": 2074, "c": "Airspace", "a": "UA.II.A.K1", "q": "If LAANC is not available for a location, the remote pilot can request airspace authorization through:", "o": ["FAADroneZone", "The nearest FBO", "A phone call to the tower on the day of flight"], "k": "FAADroneZone", "e": "FAADroneZone handles authorization requests outside LAANC.", "img": null, "area": "air"}, {"id": 2075, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class A airspace begins at:", "o": ["18,000 feet MSL", "10,000 feet MSL", "14,500 feet MSL"], "k": "18,000 feet MSL", "e": "Class A extends from 18,000 feet MSL to FL600.", "img": null, "area": "air"}, {"id": 2076, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class B airspace usually extends from the surface to:", "o": ["10,000 feet MSL", "4,000 feet AGL", "18,000 feet MSL"], "k": "10,000 feet MSL", "e": "Class B generally reaches 10,000 feet MSL around the busiest airports.", "img": null, "area": "air"}, {"id": 2077, "c": "Airspace", "a": "UA.II.A.K1", "q": "Class C airspace generally extends from the surface to:", "o": ["4,000 feet above the airport elevation", "2,500 feet above the airport elevation", "10,000 feet MSL"], "k": "4,000 feet above the airport elevation", "e": "Class C usually tops out about 4,000 feet above the airport.", "img": null, "area": "air"}, {"id": 2078, "c": "Airspace", "a": "UA.II.A.K1", "q": "When a part-time Class D tower closes, the airspace usually becomes:", "o": ["Class E or Class G, as listed in the Chart Supplement", "Class B", "Prohibited airspace"], "k": "Class E or Class G, as listed in the Chart Supplement", "e": "When the tower closes, the airspace reverts to Class E or G per the Chart Supplement.", "img": null, "area": "air"}, {"id": 2079, "c": "Airspace", "a": "UA.II.A.K1", "q": "Most Class E airspace that is not at the surface begins at:", "o": ["700 or 1,200 feet AGL", "400 feet AGL", "18,000 feet MSL"], "k": "700 or 1,200 feet AGL", "e": "Class E commonly starts at 700 feet (magenta vignette) or 1,200 feet AGL (blue vignette).", "img": null, "area": "air"}, {"id": 2080, "c": "Airspace", "a": "UA.II.A.K1", "q": "Which airspace class is uncontrolled?", "o": ["Class G", "Class E", "Class D"], "k": "Class G", "e": "Class G is the only uncontrolled class.", "img": null, "area": "air"}, {"id": 2081, "c": "Airspace", "a": "UA.II.A.K1", "q": "In an area where Class E begins at 1,200 feet AGL, a drone flying at 400 feet AGL is in:", "o": ["Class G airspace", "Class E airspace", "Class D airspace"], "k": "Class G airspace", "e": "Below the Class E floor is Class G, so no authorization is needed.", "img": null, "area": "air"}, {"id": 2082, "c": "Airspace", "a": "UA.II.A.K2", "q": "Which special use airspace is off limits to all aircraft?", "o": ["Prohibited area", "Military Operations Area", "Alert area"], "k": "Prohibited area", "e": "Prohibited areas (P-) ban flight, often for national security.", "img": null, "area": "air"}, {"id": 2083, "c": "Airspace", "a": "UA.II.A.K2", "q": "Flying in a Military Operations Area (MOA) requires:", "o": ["No permission, but extreme caution", "Permission from the using agency", "A waiver from the FAA"], "k": "No permission, but extreme caution", "e": "MOAs separate military training from IFR traffic; VFR flight is allowed with caution.", "img": null, "area": "air"}, {"id": 2084, "c": "Airspace", "a": "UA.II.A.K2", "q": "Restricted areas contain:", "o": ["Unusual, often invisible hazards such as artillery firing or guided missiles", "Only high-volume flight training", "National security sites only"], "k": "Unusual, often invisible hazards such as artillery firing or guided missiles", "e": "Restricted areas (R-) contain hazards; permission is required when active.", "img": null, "area": "air"}, {"id": 2085, "c": "Airspace", "a": "UA.II.A.K2", "q": "A Military Training Route labeled IR or VR with three digits is flown:", "o": ["Above 1,500 feet AGL", "Below 1,500 feet AGL", "Below 400 feet AGL"], "k": "Above 1,500 feet AGL", "e": "Routes with three numbers have segments above 1,500 feet AGL; four numbers mean at or below 1,500 feet AGL.", "img": null, "area": "air"}, {"id": 2086, "c": "Airspace", "a": "UA.II.A.K2", "q": "Military training routes can be dangerous to drones because:", "o": ["Military aircraft can fly very low and very fast along them", "They are always closed", "Drones cannot get GPS there"], "k": "Military aircraft can fly very low and very fast along them", "e": "MTRs with four digits can have jets as low as 100 feet AGL at speeds over 250 knots.", "img": null, "area": "air"}, {"id": 2087, "c": "Airspace", "a": "UA.II.A.K2", "q": "National Security UAS Flight Restrictions (under 99.7) apply to:", "o": ["Certain sensitive locations such as military bases and critical facilities", "All airports", "All schools"], "k": "Certain sensitive locations such as military bases and critical facilities", "e": "Special security instructions restrict drone flights over sites like military installations.", "img": null, "area": "air"}, {"id": 2088, "c": "Airspace", "a": "UA.II.A.K2", "q": "Wildfire TFRs:", "o": ["Apply to drones. Flying in one can stop firefighting aircraft", "Only apply to manned aircraft", "Are suggestions only"], "k": "Apply to drones. Flying in one can stop firefighting aircraft", "e": "Drones in a wildfire TFR can ground firefighting aircraft. If you fly, they can't.", "img": null, "area": "air"}, {"id": 2089, "c": "Airspace", "a": "UA.II.B.K5", "q": "How can a remote pilot check for NOTAMs before flight?", "o": ["Through the FAA NOTAM search website or Flight Service at 1-800-WX-BRIEF", "Only by calling the FSDO", "They are posted at every airport gate"], "k": "Through the FAA NOTAM search website or Flight Service at 1-800-WX-BRIEF", "e": "NOTAMs are available online and through Flight Service (1800wxbrief.com).", "img": null, "area": "air"}, {"id": 2090, "c": "Airspace", "a": "UA.II.B.K5", "q": "A NOTAM is:", "o": ["A notice of a change or hazard to the National Airspace System", "A weather forecast", "A type of chart"], "k": "A notice of a change or hazard to the National Airspace System", "e": "Notices to Air Missions alert pilots to hazards, closures, TFRs, and other changes.", "img": null, "area": "air"}, {"id": 2091, "c": "Airspace", "a": "UA.II.B.K5", "q": "Which tool shows TFRs on a map?", "o": ["The FAA TFR website (tfr.faa.gov) and the B4UFLY app", "The sectional chart legend", "A METAR"], "k": "The FAA TFR website (tfr.faa.gov) and the B4UFLY app", "e": "TFRs are temporary and not on printed charts, so check the TFR site or an approved app.", "img": null, "area": "air"}, {"id": 2092, "c": "Airspace", "a": "UA.II.A.K3", "q": "Without a waiver, a remote pilot must avoid flying over a stadium during a major sporting event because:", "o": ["A TFR typically covers the venue", "Stadiums are always Class B", "The crowd is a VO"], "k": "A TFR typically covers the venue", "e": "Qualifying events have a TFR from 1 hour before until 1 hour after.", "img": null, "area": "air"}, {"id": 2093, "c": "Airspace", "a": "UA.II.A.K1", "q": "Washington, D.C. has a special flight rules area. Drone flight within 15 miles of Reagan National Airport is:", "o": ["Prohibited without specific FAA and security approvals", "Allowed below 400 feet", "Allowed with LAANC"], "k": "Prohibited without specific FAA and security approvals", "e": "The DC Flight Restricted Zone requires special approval; it is largely a No Drone Zone.", "img": null, "area": "air"}, {"id": 2094, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "At a non-towered airport, the recommended traffic pattern direction is:", "o": ["Left turns, unless the chart or Chart Supplement shows right traffic", "Right turns always", "Pilot's choice"], "k": "Left turns, unless the chart or Chart Supplement shows right traffic", "e": "Standard traffic patterns use left turns; RP on the chart means right traffic.", "img": null, "area": "ops"}, {"id": 2095, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "A pilot reports 'turning base for runway 18.' The aircraft is:", "o": ["About to turn onto final approach for runway 18", "Departing runway 18", "Taxiing to runway 18"], "k": "About to turn onto final approach for runway 18", "e": "The base leg comes right before the final approach.", "img": null, "area": "ops"}, {"id": 2096, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "The crosswind leg of the traffic pattern is:", "o": ["Flown perpendicular to the runway after takeoff", "Parallel to the runway opposite the landing direction", "The final approach"], "k": "Flown perpendicular to the runway after takeoff", "e": "After departure, the crosswind leg is perpendicular to the runway.", "img": null, "area": "ops"}, {"id": 2097, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "An aircraft is on a left downwind for runway 9. Where is it?", "o": ["North of the runway, flying west", "South of the runway, flying west", "North of the runway, flying east"], "k": "North of the runway, flying west", "e": "Runway 9 heads east; left traffic puts the downwind north of the runway, heading west.", "img": null, "area": "ops"}, {"id": 2098, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "A pilot announces 'Cooperstown traffic, Cessna 123AB, 10 miles south, inbound landing runway 36.' The aircraft is:", "o": ["Approaching from the south, landing to the north", "Leaving to the south", "Flying over the airport"], "k": "Approaching from the south, landing to the north", "e": "Runway 36 lands northbound, and the aircraft is 10 miles south.", "img": null, "area": "ops"}, {"id": 2099, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "Radio calls at non-towered airports usually begin with:", "o": ["The airport name, then 'traffic'", "The aircraft's speed", "The word 'Mayday'"], "k": "The airport name, then 'traffic'", "e": "Self-announced calls start with the airport name plus 'traffic' so pilots know which airport you mean.", "img": null, "area": "ops"}, {"id": 2100, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "How is the number '1500' spoken in aviation phraseology?", "o": ["One thousand five hundred", "Fifteen hundred", "One five zero zero"], "k": "One thousand five hundred", "e": "Altitudes are said in thousands and hundreds: one thousand five hundred.", "img": null, "area": "ops"}, {"id": 2101, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "How is 'niner' used in aviation radio?", "o": ["It is how the number 9 is pronounced", "It means 'repeat'", "It is a warning"], "k": "It is how the number 9 is pronounced", "e": "Nine is pronounced 'niner' to avoid confusion with 'nein' or 'five.'", "img": null, "area": "ops"}, {"id": 2102, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "The phonetic alphabet word for the letter 'G' is:", "o": ["Golf", "George", "Gamma"], "k": "Golf", "e": "The ICAO phonetic alphabet uses Golf for G.", "img": null, "area": "ops"}, {"id": 2103, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "Traffic reported at '2 o'clock' is:", "o": ["Ahead and to the right", "Behind and to the left", "Directly ahead"], "k": "Ahead and to the right", "e": "Clock positions are relative to the aircraft's nose: 12 is ahead, 3 is right.", "img": null, "area": "ops"}, {"id": 2104, "c": "Airport Ops", "a": "UA.V.B.K6", "q": "The Chart Supplement (formerly Airport/Facility Directory) contains:", "o": ["Detailed airport information such as runways, frequencies, and services", "Only weather data", "Only drone rules"], "k": "Detailed airport information such as runways, frequencies, and services", "e": "The Chart Supplement is the most comprehensive source of airport information.", "img": null, "area": "ops"}, {"id": 2105, "c": "Airport Ops", "a": "UA.V.B.K6", "q": "Which source gives the most comprehensive information on a given airport?", "o": ["The Chart Supplement", "The sectional chart", "A METAR"], "k": "The Chart Supplement", "e": "The Chart Supplement contains far more airport detail than a sectional chart.", "img": null, "area": "ops"}, {"id": 2106, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "A runway is numbered 4 on one end. What is the number on the opposite end?", "o": ["22", "14", "40"], "k": "22", "e": "Runway numbers differ by 18 (180 degrees): 4 + 18 = 22.", "img": null, "area": "ops"}, {"id": 2107, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "Runway 13 points roughly toward:", "o": ["130 degrees magnetic, southeast", "013 degrees, north", "310 degrees, northwest"], "k": "130 degrees magnetic, southeast", "e": "Runway numbers are the magnetic heading rounded to the nearest 10 degrees, with the last zero dropped.", "img": null, "area": "ops"}, {"id": 2108, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "A runway holding position marking is:", "o": ["Four yellow lines, two solid and two dashed, across the taxiway", "A white X", "Green lights"], "k": "Four yellow lines, two solid and two dashed, across the taxiway", "e": "Stop at the solid lines unless cleared; the dashed side faces the runway.", "img": null, "area": "ops"}, {"id": 2109, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "Mandatory instruction signs at an airport have:", "o": ["White letters on a red background", "Black letters on a yellow background", "Yellow letters on a black background"], "k": "White letters on a red background", "e": "Red signs with white text mark runway entrances and critical areas.", "img": null, "area": "ops"}, {"id": 2110, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "A taxiway location sign shows:", "o": ["Yellow letters on a black background", "Black letters on a yellow background", "White letters on red"], "k": "Yellow letters on a black background", "e": "Location signs tell you which taxiway you are on.", "img": null, "area": "ops"}, {"id": 2111, "c": "Airport Ops", "a": "UA.V.A.K2", "q": "A sign with black letters on a yellow background and an arrow is a:", "o": ["Direction sign", "Location sign", "Mandatory sign"], "k": "Direction sign", "e": "Direction signs point the way to other taxiways.", "img": null, "area": "ops"}, {"id": 2112, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "A rotating airport beacon that operates during the day may mean:", "o": ["Weather is below basic VFR minimums in Class B, C, D, or surface E airspace", "The airport is closed", "A military exercise"], "k": "Weather is below basic VFR minimums in Class B, C, D, or surface E airspace", "e": "Daytime beacon operation can indicate IFR conditions (ceiling below 1,000 feet or visibility under 3 miles).", "img": null, "area": "ops"}, {"id": 2113, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "A wind cone (windsock) that is fully extended indicates winds of about:", "o": ["15 knots or more", "5 knots", "30 knots or more"], "k": "15 knots or more", "e": "A fully extended windsock usually means about 15 knots or more.", "img": null, "area": "ops"}, {"id": 2114, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "What frequency is the international emergency frequency?", "o": ["121.5 MHz", "122.9 MHz", "123.0 MHz"], "k": "121.5 MHz", "e": "121.5 MHz is the VHF emergency (guard) frequency.", "img": null, "area": "ops"}, {"id": 2115, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "When there is no tower, UNICOM, or FSS at an airport, pilots self-announce on:", "o": ["MULTICOM, 122.9", "121.5", "118.0"], "k": "MULTICOM, 122.9", "e": "With no other frequency listed, pilots use MULTICOM 122.9 as the CTAF.", "img": null, "area": "ops"}, {"id": 2116, "c": "Airport Ops", "a": "UA.V.A.K3", "q": "Pilots at non-towered airports should begin self-announcing when they are about:", "o": ["10 miles out", "2 miles out", "25 miles out"], "k": "10 miles out", "e": "The AIM recommends announcing about 10 miles from the airport.", "img": null, "area": "ops"}, {"id": 2117, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "The term 'final approach' refers to:", "o": ["The path aligned with the runway in the direction of landing", "The leg parallel to the runway", "Climbing out after departure"], "k": "The path aligned with the runway in the direction of landing", "e": "Final approach is the last leg, lined up with the runway.", "img": null, "area": "ops"}, {"id": 2118, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "ATIS broadcasts:", "o": ["Recorded weather, active runways, and airport information at busier airports", "Live ATC instructions", "Emergency alerts only"], "k": "Recorded weather, active runways, and airport information at busier airports", "e": "ATIS is updated hourly or with changes and identified by a phonetic letter.", "img": null, "area": "ops"}, {"id": 2119, "c": "Airport Ops", "a": "UA.V.B.K3", "q": "AWOS and ASOS are:", "o": ["Automated weather observing systems", "Types of airspace", "Radio phraseology"], "k": "Automated weather observing systems", "e": "These stations broadcast automated weather, often on a frequency shown on the chart.", "img": null, "area": "ops"}, {"id": 2120, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "A segmented circle at a non-towered airport shows:", "o": ["Traffic pattern direction and wind direction (with the wind indicator)", "Runway closures", "Fuel availability"], "k": "Traffic pattern direction and wind direction (with the wind indicator)", "e": "Traffic pattern indicators on the segmented circle show which way turns are made.", "img": null, "area": "ops"}, {"id": 2121, "c": "Airport Ops", "a": "UA.V.A.K1", "q": "A tetrahedron at an airport indicates:", "o": ["Wind direction or landing direction", "Airport elevation", "Fuel type"], "k": "Wind direction or landing direction", "e": "The small end of a tetrahedron points into the wind (or the landing direction).", "img": null, "area": "ops"}, {"id": 2122, "c": "Charts", "a": "UA.V.B.K6", "q": "Lines of latitude measure:", "o": ["Degrees north or south of the equator", "Degrees east or west of Greenwich", "Elevation"], "k": "Degrees north or south of the equator", "e": "Latitude lines run east to west and measure north or south of the equator.", "img": null, "area": "air"}, {"id": 2123, "c": "Charts", "a": "UA.V.B.K6", "q": "Lines of longitude measure:", "o": ["Degrees east or west of the prime meridian", "Degrees north or south of the equator", "Distance to the nearest airport"], "k": "Degrees east or west of the prime meridian", "e": "Longitude lines run north to south and measure east or west of Greenwich, England.", "img": null, "area": "air"}, {"id": 2124, "c": "Charts", "a": "UA.V.B.K6", "q": "On a sectional chart, each degree of latitude or longitude is divided into:", "o": ["60 minutes", "100 minutes", "360 minutes"], "k": "60 minutes", "e": "A degree has 60 minutes; sectionals mark tick lines every minute.", "img": null, "area": "air"}, {"id": 2125, "c": "Charts", "a": "UA.V.B.K6", "q": "One minute of latitude equals about:", "o": ["1 nautical mile", "1 statute mile", "10 nautical miles"], "k": "1 nautical mile", "e": "One minute of latitude is approximately one nautical mile.", "img": null, "area": "air"}, {"id": 2126, "c": "Charts", "a": "UA.V.B.K6", "q": "The scale of a sectional aeronautical chart is:", "o": ["1:500,000 (about 6.86 nautical miles per inch)", "1:250,000", "1:1,000,000"], "k": "1:500,000 (about 6.86 nautical miles per inch)", "e": "Sectionals are 1:500,000; terminal area charts are 1:250,000.", "img": null, "area": "air"}, {"id": 2127, "c": "Charts", "a": "UA.V.B.K6", "q": "How often are sectional charts normally updated?", "o": ["Every 56 days", "Every year", "Every 28 days"], "k": "Every 56 days", "e": "VFR sectional charts are on a 56-day cycle.", "img": null, "area": "air"}, {"id": 2128, "c": "Charts", "a": "UA.V.B.K6", "q": "Airport elevation on a sectional chart is given in:", "o": ["Feet MSL", "Feet AGL", "Meters"], "k": "Feet MSL", "e": "Airport elevations are in feet above mean sea level.", "img": null, "area": "air"}, {"id": 2129, "c": "Charts", "a": "UA.V.B.K6", "q": "An airport data block reads 'CT - 118.3.' What does CT mean?", "o": ["Control tower frequency", "Common traffic frequency", "Center traffic"], "k": "Control tower frequency", "e": "CT shows the tower frequency; a star after it means part-time.", "img": null, "area": "air"}, {"id": 2130, "c": "Charts", "a": "UA.V.B.K6", "q": "An airport data block shows 'C' in a solid circle. This symbol indicates:", "o": ["The Common Traffic Advisory Frequency (CTAF)", "A Class C airport", "A closed airport"], "k": "The Common Traffic Advisory Frequency (CTAF)", "e": "The C in a circle marks the CTAF.", "img": null, "area": "air"}, {"id": 2131, "c": "Charts", "a": "UA.V.B.K6", "q": "Obstructions shown in bold numbers near a symbol are listed as:", "o": ["Feet MSL with AGL in parentheses", "Feet AGL with MSL in parentheses", "Meters"], "k": "Feet MSL with AGL in parentheses", "e": "For example, 1548 (355) means the top is 1,548 feet MSL and 355 feet AGL.", "img": null, "area": "air"}, {"id": 2132, "c": "Charts", "a": "UA.V.B.K6", "q": "On a sectional chart, an obstruction 1,000 feet AGL or higher is shown with:", "o": ["A taller symbol than lower obstructions", "A small dot", "No symbol"], "k": "A taller symbol than lower obstructions", "e": "The legend uses a larger symbol for obstructions 1,000 feet AGL and higher.", "img": null, "area": "air"}, {"id": 2133, "c": "Charts", "a": "UA.V.B.K6", "q": "Group obstruction symbols mean:", "o": ["Two or more obstructions close together", "An airport", "A tower under construction"], "k": "Two or more obstructions close together", "e": "Group obstructions show multiple structures in one spot.", "img": null, "area": "air"}, {"id": 2134, "c": "Charts", "a": "UA.V.B.K6", "q": "High-intensity lights on an obstruction are shown by:", "o": ["Lightning-like flash marks around the obstruction symbol", "A star", "A circle"], "k": "Lightning-like flash marks around the obstruction symbol", "e": "Flash marks indicate high-intensity obstruction lights that may operate part time.", "img": null, "area": "air"}, {"id": 2135, "c": "Charts", "a": "UA.V.B.K6", "q": "On a sectional chart, Class C airspace boundaries are shown with:", "o": ["Solid magenta lines", "Dashed blue lines", "Shaded blue lines"], "k": "Solid magenta lines", "e": "Class C is depicted in solid magenta.", "img": null, "area": "air"}, {"id": 2136, "c": "Charts", "a": "UA.V.B.K6", "q": "A Class C sector labeled '40/15' means the airspace extends from:", "o": ["1,500 feet MSL to 4,000 feet MSL", "1,500 feet AGL to 4,000 feet AGL", "400 feet to 1,500 feet"], "k": "1,500 feet MSL to 4,000 feet MSL", "e": "Numbers are in hundreds of feet MSL: ceiling over floor.", "img": null, "area": "air"}, {"id": 2137, "c": "Charts", "a": "UA.V.B.K6", "q": "A Class B sector labeled '100/SFC' means:", "o": ["From the surface to 10,000 feet MSL", "From 100 feet to the surface", "Floor 10,000 feet"], "k": "From the surface to 10,000 feet MSL", "e": "SFC is the surface; 100 is 10,000 feet MSL.", "img": null, "area": "air"}, {"id": 2138, "c": "Charts", "a": "UA.V.B.K6", "q": "Within a Class B sector labeled '100/30,' a drone at 400 feet AGL where the ground is 600 feet MSL is:", "o": ["Below Class B (top of the drone is 1,000 feet MSL, under the 3,000-foot floor)", "Inside Class B", "Above Class B"], "k": "Below Class B (top of the drone is 1,000 feet MSL, under the 3,000-foot floor)", "e": "400 + 600 = 1,000 feet MSL, which is below the 3,000-foot MSL floor.", "img": null, "area": "air"}, {"id": 2139, "c": "Charts", "a": "UA.V.B.K6", "q": "A blue box with a number like [25] in Class D airspace shows:", "o": ["The Class D ceiling, 2,500 feet MSL", "The airport elevation", "The tower frequency"], "k": "The Class D ceiling, 2,500 feet MSL", "e": "Bracketed numbers give the Class D ceiling in hundreds of feet MSL.", "img": null, "area": "air"}, {"id": 2140, "c": "Charts", "a": "UA.V.B.K6", "q": "Which airport symbol indicates a hard-surfaced runway 1,500 to 8,069 feet long?", "o": ["A circle with the runway drawn inside", "A circle with an R", "An open circle with no runway"], "k": "A circle with the runway drawn inside", "e": "The legend shows hard-surfaced runways inside the circle; longer runways are drawn as a runway outline.", "img": null, "area": "air"}, {"id": 2141, "c": "Charts", "a": "UA.V.B.K6", "q": "An airport symbol that is magenta with tick marks around it means:", "o": ["A non-towered airport with services available", "A towered airport", "A heliport"], "k": "A non-towered airport with services available", "e": "Magenta means no tower; tick marks mean fuel or services.", "img": null, "area": "air"}, {"id": 2142, "c": "Charts", "a": "UA.V.B.K6", "q": "An 'H' in a circle on a sectional chart is a:", "o": ["Heliport", "Hospital", "Hazard area"], "k": "Heliport", "e": "The H symbol marks a heliport.", "img": null, "area": "air"}, {"id": 2143, "c": "Charts", "a": "UA.V.B.K6", "q": "A small 'x' inside an airport circle (or 'X' on a runway symbol) indicates:", "o": ["An abandoned airport", "A seaplane base", "A military airport"], "k": "An abandoned airport", "e": "The legend shows abandoned airports with an X.", "img": null, "area": "air"}, {"id": 2144, "c": "Charts", "a": "UA.V.B.K6", "q": "Seaplane bases are shown with:", "o": ["An anchor symbol", "A wave symbol", "A boat"], "k": "An anchor symbol", "e": "The anchor symbol marks a seaplane base.", "img": null, "area": "air"}, {"id": 2145, "c": "Charts", "a": "UA.V.B.K6", "q": "Isogonic lines on a sectional chart show:", "o": ["Magnetic variation", "Elevation", "Class E airspace"], "k": "Magnetic variation", "e": "The dashed magenta isogonic line shows magnetic variation (for example, 1 degree E).", "img": null, "area": "air"}, {"id": 2146, "c": "Charts", "a": "UA.V.B.K6", "q": "A blue airport with a 'C' in a circle next to the tower frequency means:", "o": ["The tower frequency is also the CTAF when the tower is closed", "The airport is Class C", "The airport is closed"], "k": "The tower frequency is also the CTAF when the tower is closed", "e": "When the tower is part-time, its frequency becomes the CTAF after hours.", "img": null, "area": "air"}, {"id": 2147, "c": "Charts", "a": "UA.V.B.K6", "q": "Terminal Area Charts (TACs) cover:", "o": ["Class B airspace areas at a larger scale (1:250,000)", "Only Class G", "The whole state"], "k": "Class B airspace areas at a larger scale (1:250,000)", "e": "TACs show Class B areas in more detail than sectionals.", "img": null, "area": "air"}, {"id": 2148, "c": "Charts", "a": "UA.V.B.K6", "q": "On a sectional chart, the outer boundary of a Mode C veil (30 NM from a Class B primary airport) is shown by:", "o": ["A thin solid magenta circle", "A dashed blue circle", "A shaded blue vignette"], "k": "A thin solid magenta circle", "e": "The Mode C veil is a thin magenta circle; it does not change drone requirements.", "img": null, "area": "air"}, {"id": 2149, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'KDFW 121853Z 18012G20KT' means the wind is:", "o": ["From 180 degrees at 12 knots, gusting to 20 knots", "Toward 180 degrees at 12 knots", "From 120 degrees at 18 knots"], "k": "From 180 degrees at 12 knots, gusting to 20 knots", "e": "Wind is reported as the direction it blows from (true), speed, then G for gusts.", "img": null, "area": "wx"}, {"id": 2150, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, the time '121853Z' means:", "o": ["The 12th day of the month at 1853 UTC (Zulu)", "12:18 local time", "December 18 at 5:30"], "k": "The 12th day of the month at 1853 UTC (Zulu)", "e": "The first two digits are the day; the next four are the time in UTC.", "img": null, "area": "wx"}, {"id": 2151, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, '10SM' means:", "o": ["Visibility 10 statute miles", "Clouds at 1,000 feet", "Wind 10 knots"], "k": "Visibility 10 statute miles", "e": "SM stands for statute miles of visibility.", "img": null, "area": "wx"}, {"id": 2152, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, '1/2SM FG' means:", "o": ["Visibility one-half statute mile in fog", "Fog at 1,200 feet", "Half of the sky is covered"], "k": "Visibility one-half statute mile in fog", "e": "FG is fog; it is reported when visibility is less than 5/8 mile.", "img": null, "area": "wx"}, {"id": 2153, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'SCT025' means:", "o": ["Scattered clouds at 2,500 feet AGL", "Scattered clouds at 25,000 feet", "Visibility 2.5 miles"], "k": "Scattered clouds at 2,500 feet AGL", "e": "Cloud heights are in hundreds of feet AGL; SCT is 3/8 to 4/8 coverage.", "img": null, "area": "wx"}, {"id": 2154, "c": "Weather", "a": "UA.III.A.K2", "q": "Which METAR cloud coverage is considered a ceiling?", "o": ["Broken (BKN) or overcast (OVC)", "Few (FEW)", "Scattered (SCT)"], "k": "Broken (BKN) or overcast (OVC)", "e": "A ceiling is the lowest broken or overcast layer, or vertical visibility.", "img": null, "area": "wx"}, {"id": 2155, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'VV004' means:", "o": ["Vertical visibility of 400 feet into an obscuration", "Visibility 4 miles", "Variable winds at 4 knots"], "k": "Vertical visibility of 400 feet into an obscuration", "e": "VV is vertical visibility into an indefinite ceiling, such as fog.", "img": null, "area": "wx"}, {"id": 2156, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, '22/18' means:", "o": ["Temperature 22 degrees C, dew point 18 degrees C", "Wind 220 at 18 knots", "Visibility 22 miles"], "k": "Temperature 22 degrees C, dew point 18 degrees C", "e": "Temperature and dew point are in Celsius.", "img": null, "area": "wx"}, {"id": 2157, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'M02/M05' means:", "o": ["Temperature minus 2 C, dew point minus 5 C", "Temperature 2 C, dew point 5 C", "Missing data"], "k": "Temperature minus 2 C, dew point minus 5 C", "e": "M means minus.", "img": null, "area": "wx"}, {"id": 2158, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, '-RA' means:", "o": ["Light rain", "Heavy rain", "No rain"], "k": "Light rain", "e": "A minus sign means light; a plus sign means heavy.", "img": null, "area": "wx"}, {"id": 2159, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, '+TSRA' means:", "o": ["Thunderstorm with heavy rain", "Light thunderstorm", "Tornado"], "k": "Thunderstorm with heavy rain", "e": "+ is heavy intensity, TS is thunderstorm, RA is rain.", "img": null, "area": "wx"}, {"id": 2160, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'HZ' means:", "o": ["Haze", "Hail", "Hazard"], "k": "Haze", "e": "HZ is haze; GR is hail.", "img": null, "area": "wx"}, {"id": 2161, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'SPECI' means:", "o": ["A special, unscheduled report issued because of a significant change", "A routine hourly report", "A forecast"], "k": "A special, unscheduled report issued because of a significant change", "e": "SPECI reports are issued between regular METARs when conditions change significantly.", "img": null, "area": "wx"}, {"id": 2162, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR, 'AUTO' means:", "o": ["The report came from an automated station with no human input", "Altimeter setting", "The report is updated automatically each minute"], "k": "The report came from an automated station with no human input", "e": "AUTO marks a fully automated report.", "img": null, "area": "wx"}, {"id": 2163, "c": "Weather", "a": "UA.III.A.K2", "q": "In a METAR remark, 'RMK AO2' means:", "o": ["An automated station with a precipitation sensor", "Altimeter out of service", "Overcast at 200 feet"], "k": "An automated station with a precipitation sensor", "e": "AO2 stations can tell rain from snow; AO1 cannot.", "img": null, "area": "wx"}, {"id": 2164, "c": "Weather", "a": "UA.III.A.K2", "q": "In a TAF, 'TEMPO' means:", "o": ["Temporary changes expected for less than an hour at a time and less than half the period", "A permanent change", "A tornado warning"], "k": "Temporary changes expected for less than an hour at a time and less than half the period", "e": "TEMPO describes temporary fluctuations.", "img": null, "area": "wx"}, {"id": 2165, "c": "Weather", "a": "UA.III.A.K2", "q": "In a TAF, 'PROB30' means:", "o": ["A 30 percent probability of the condition occurring", "Visibility 30 miles", "The forecast is valid 30 hours"], "k": "A 30 percent probability of the condition occurring", "e": "PROB30 or PROB40 shows the chance of thunderstorms or precipitation.", "img": null, "area": "wx"}, {"id": 2166, "c": "Weather", "a": "UA.III.A.K2", "q": "In a TAF, 'P6SM' means:", "o": ["Visibility greater than 6 statute miles", "Precipitation 6 inches", "Pressure 6 millibars"], "k": "Visibility greater than 6 statute miles", "e": "P means 'plus,' or more than.", "img": null, "area": "wx"}, {"id": 2167, "c": "Weather", "a": "UA.III.A.K2", "q": "Times in a TAF and METAR are given in:", "o": ["UTC (Zulu time)", "Local time", "Eastern time"], "k": "UTC (Zulu time)", "e": "All aviation weather times are UTC.", "img": null, "area": "wx"}, {"id": 2168, "c": "Weather", "a": "UA.III.A.K2", "q": "A TAF normally covers an area within:", "o": ["5 statute miles of the center of the runway complex", "50 miles of the airport", "The whole state"], "k": "5 statute miles of the center of the runway complex", "e": "TAFs forecast conditions within 5 SM of the airport.", "img": null, "area": "wx"}, {"id": 2169, "c": "Weather", "a": "UA.III.A.K1", "q": "What is a common source of weather briefings for remote pilots?", "o": ["Flight Service (1800wxbrief.com) and aviationweather.gov", "Social media", "A car radio"], "k": "Flight Service (1800wxbrief.com) and aviationweather.gov", "e": "Official sources include Flight Service and the Aviation Weather Center.", "img": null, "area": "wx"}, {"id": 2170, "c": "Weather", "a": "UA.III.A.K1", "q": "An outlook briefing is best for:", "o": ["Planning a flight 6 or more hours away", "A flight leaving right now", "Updating a briefing in flight"], "k": "Planning a flight 6 or more hours away", "e": "Outlook briefings are for flights 6 or more hours out.", "img": null, "area": "wx"}, {"id": 2171, "c": "Weather", "a": "UA.III.A.K1", "q": "A standard briefing is requested when:", "o": ["You have not received a previous briefing for the flight", "You only need one specific item", "The flight is a week away"], "k": "You have not received a previous briefing for the flight", "e": "A standard briefing is the most complete.", "img": null, "area": "wx"}, {"id": 2172, "c": "Weather", "a": "UA.III.A.K1", "q": "An abbreviated briefing is used to:", "o": ["Update a previous briefing or get specific information", "Get a full first briefing", "Plan a flight a week away"], "k": "Update a previous briefing or get specific information", "e": "Abbreviated briefings supplement earlier data.", "img": null, "area": "wx"}, {"id": 2173, "c": "Weather", "a": "UA.III.B.K1", "q": "Air pressure is measured with a:", "o": ["Barometer", "Thermometer", "Hygrometer"], "k": "Barometer", "e": "A barometer measures atmospheric pressure, usually in inches of mercury.", "img": null, "area": "wx"}, {"id": 2174, "c": "Weather", "a": "UA.III.B.K1", "q": "Standard temperature at sea level is:", "o": ["15 degrees C (59 degrees F)", "0 degrees C (32 degrees F)", "20 degrees C (68 degrees F)"], "k": "15 degrees C (59 degrees F)", "e": "The standard atmosphere is 15 C and 29.92 inHg at sea level.", "img": null, "area": "wx"}, {"id": 2175, "c": "Weather", "a": "UA.III.B.K1", "q": "In the standard atmosphere, temperature decreases about:", "o": ["2 degrees C per 1,000 feet", "1 degree C per 1,000 feet", "5 degrees C per 1,000 feet"], "k": "2 degrees C per 1,000 feet", "e": "The standard lapse rate is about 2 C (3.5 F) per 1,000 feet.", "img": null, "area": "wx"}, {"id": 2176, "c": "Weather", "a": "UA.III.B.K1", "q": "Air flows around a high-pressure system in the Northern Hemisphere:", "o": ["Clockwise and outward", "Counterclockwise and inward", "Straight up"], "k": "Clockwise and outward", "e": "Highs rotate clockwise and outward; lows rotate counterclockwise and inward.", "img": null, "area": "wx"}, {"id": 2177, "c": "Weather", "a": "UA.III.B.K1", "q": "Low-pressure systems are usually associated with:", "o": ["Rising air, clouds, and precipitation", "Sinking air and clear skies", "Calm, dry weather"], "k": "Rising air, clouds, and precipitation", "e": "Rising air in a low cools and forms clouds.", "img": null, "area": "wx"}, {"id": 2178, "c": "Weather", "a": "UA.III.B.K1", "q": "What causes wind?", "o": ["Differences in air pressure, which come from uneven heating of the earth", "The rotation of the moon", "Ocean currents only"], "k": "Differences in air pressure, which come from uneven heating of the earth", "e": "Air moves from high pressure to low pressure.", "img": null, "area": "wx"}, {"id": 2179, "c": "Weather", "a": "UA.III.B.K1", "q": "The Coriolis force causes wind in the Northern Hemisphere to be deflected:", "o": ["To the right", "To the left", "Straight down"], "k": "To the right", "e": "Earth's rotation deflects moving air to the right in the Northern Hemisphere.", "img": null, "area": "wx"}, {"id": 2180, "c": "Weather", "a": "UA.III.B.K1", "q": "What are the three things needed for a thunderstorm?", "o": ["Sufficient moisture, an unstable lapse rate, and a lifting force", "Cold air, wind, and sunshine", "High pressure, dry air, and calm wind"], "k": "Sufficient moisture, an unstable lapse rate, and a lifting force", "e": "Thunderstorms need moisture, instability, and lift.", "img": null, "area": "wx"}, {"id": 2181, "c": "Weather", "a": "UA.III.B.K1", "q": "What are the three stages of a thunderstorm?", "o": ["Cumulus, mature, and dissipating", "Formation, peak, and end", "Cirrus, stratus, and cumulus"], "k": "Cumulus, mature, and dissipating", "e": "Updrafts build the cumulus stage, rain begins the mature stage, and downdrafts dominate dissipating.", "img": null, "area": "wx"}, {"id": 2182, "c": "Weather", "a": "UA.III.B.K1", "q": "The mature stage of a thunderstorm begins when:", "o": ["Precipitation starts falling from the cloud base", "The anvil top forms", "The cloud first appears"], "k": "Precipitation starts falling from the cloud base", "e": "Rain at the surface marks the mature stage, with both updrafts and downdrafts.", "img": null, "area": "wx"}, {"id": 2183, "c": "Weather", "a": "UA.III.B.K1", "q": "The dissipating stage of a thunderstorm is mainly:", "o": ["Downdrafts", "Updrafts", "Strong lift"], "k": "Downdrafts", "e": "Downdrafts dominate as the storm dies.", "img": null, "area": "wx"}, {"id": 2184, "c": "Weather", "a": "UA.III.B.K1", "q": "A microburst can produce downdrafts as strong as:", "o": ["6,000 feet per minute", "500 feet per minute", "60 feet per minute"], "k": "6,000 feet per minute", "e": "Microbursts are small, intense downdrafts that last about 15 minutes.", "img": null, "area": "wx"}, {"id": 2185, "c": "Weather", "a": "UA.III.B.K1", "q": "A microburst usually lasts:", "o": ["About 15 minutes or less", "Several hours", "All day"], "k": "About 15 minutes or less", "e": "Microbursts are short-lived but extremely dangerous.", "img": null, "area": "wx"}, {"id": 2186, "c": "Weather", "a": "UA.III.B.K1", "q": "Lightning is associated with:", "o": ["All thunderstorms", "Only tornadoes", "Only cold fronts"], "k": "All thunderstorms", "e": "By definition, a thunderstorm has lightning and thunder.", "img": null, "area": "wx"}, {"id": 2187, "c": "Weather", "a": "UA.III.B.K1", "q": "How far from a thunderstorm can severe turbulence and hail occur?", "o": ["Up to 20 miles", "Only directly under it", "1 mile"], "k": "Up to 20 miles", "e": "Pilots are taught to stay at least 20 miles from severe thunderstorms.", "img": null, "area": "wx"}, {"id": 2188, "c": "Weather", "a": "UA.III.B.K1", "q": "Cumulonimbus clouds are:", "o": ["The most dangerous clouds, producing thunderstorms", "Thin, high ice clouds", "Low fog"], "k": "The most dangerous clouds, producing thunderstorms", "e": "Cumulonimbus contain nearly every weather hazard.", "img": null, "area": "wx"}, {"id": 2189, "c": "Weather", "a": "UA.III.B.K1", "q": "Towering cumulus clouds indicate:", "o": ["Unstable air and possible thunderstorm development", "Stable air", "Clear weather"], "k": "Unstable air and possible thunderstorm development", "e": "Vertical development shows instability and lift.", "img": null, "area": "wx"}, {"id": 2190, "c": "Weather", "a": "UA.III.B.K1", "q": "Stratus clouds usually indicate:", "o": ["Stable air and smooth conditions", "Unstable air and turbulence", "Thunderstorms"], "k": "Stable air and smooth conditions", "e": "Layered clouds form in stable air.", "img": null, "area": "wx"}, {"id": 2191, "c": "Weather", "a": "UA.III.B.K1", "q": "Lenticular clouds near mountains indicate:", "o": ["Mountain wave turbulence", "Calm winds", "An approaching warm front only"], "k": "Mountain wave turbulence", "e": "Standing lens-shaped clouds form in mountain waves with strong turbulence.", "img": null, "area": "wx"}, {"id": 2192, "c": "Weather", "a": "UA.III.B.K1", "q": "Nimbus as part of a cloud name means:", "o": ["Rain-bearing", "High altitude", "Thin"], "k": "Rain-bearing", "e": "Nimbo- or -nimbus clouds produce precipitation.", "img": null, "area": "wx"}, {"id": 2193, "c": "Weather", "a": "UA.III.B.K1", "q": "A cold front typically brings:", "o": ["Cumuliform clouds, showers, gusty winds, and a quick change", "Steady rain for days", "Fog and drizzle only"], "k": "Cumuliform clouds, showers, gusty winds, and a quick change", "e": "Cold fronts move fast with narrow bands of showers and storms.", "img": null, "area": "wx"}, {"id": 2194, "c": "Weather", "a": "UA.III.B.K1", "q": "A warm front typically brings:", "o": ["Stratiform clouds, steady precipitation, and poor visibility", "Fast-moving thunderstorms", "Clear skies"], "k": "Stratiform clouds, steady precipitation, and poor visibility", "e": "Warm fronts move slowly with widespread layered clouds.", "img": null, "area": "wx"}, {"id": 2195, "c": "Weather", "a": "UA.III.B.K1", "q": "After a cold front passes, you can usually expect:", "o": ["Cooler temperatures, rising pressure, and better visibility", "Warmer temperatures", "Fog"], "k": "Cooler temperatures, rising pressure, and better visibility", "e": "Post-frontal air is cooler and clearer.", "img": null, "area": "wx"}, {"id": 2196, "c": "Weather", "a": "UA.III.B.K1", "q": "A stationary front is a front that:", "o": ["Has little or no movement", "Moves faster than 30 knots", "Exists only over oceans"], "k": "Has little or no movement", "e": "Stationary fronts can bring prolonged bad weather.", "img": null, "area": "wx"}, {"id": 2197, "c": "Weather", "a": "UA.III.B.K1", "q": "An occluded front forms when:", "o": ["A fast-moving cold front catches up to a warm front", "Two high-pressure systems meet", "The sun heats the ground"], "k": "A fast-moving cold front catches up to a warm front", "e": "Occlusions combine features of both fronts.", "img": null, "area": "wx"}, {"id": 2198, "c": "Weather", "a": "UA.III.B.K1", "q": "A wind shift is a common sign of:", "o": ["A frontal passage", "A temperature inversion", "Fog forming"], "k": "A frontal passage", "e": "Wind direction changes when a front passes.", "img": null, "area": "wx"}, {"id": 2199, "c": "Weather", "a": "UA.III.B.K1", "q": "Steam fog forms when:", "o": ["Cold, dry air moves over warmer water", "Warm air moves over cold ground", "The ground cools on a clear night"], "k": "Cold, dry air moves over warmer water", "e": "Steam fog rises from water that is warmer than the air above it.", "img": null, "area": "wx"}, {"id": 2200, "c": "Weather", "a": "UA.III.B.K1", "q": "Upslope fog forms when:", "o": ["Moist, stable air is pushed up sloping terrain and cools", "Air cools over a lake", "Air sinks down a mountain"], "k": "Moist, stable air is pushed up sloping terrain and cools", "e": "Lifting air cools adiabatically to its dew point.", "img": null, "area": "wx"}, {"id": 2201, "c": "Weather", "a": "UA.III.B.K1", "q": "Radiation fog is most likely:", "o": ["On clear, calm nights over low, flat land", "On windy afternoons", "Over warm oceans"], "k": "On clear, calm nights over low, flat land", "e": "The ground cools by radiation, chilling the air above it to the dew point.", "img": null, "area": "wx"}, {"id": 2202, "c": "Weather", "a": "UA.III.B.K1", "q": "When the temperature and dew point are close together, the air is:", "o": ["Near saturation, so fog, clouds, or rain may form", "Very dry", "Unstable"], "k": "Near saturation, so fog, clouds, or rain may form", "e": "A small spread means high relative humidity.", "img": null, "area": "wx"}, {"id": 2203, "c": "Weather", "a": "UA.III.B.K1", "q": "Frost on a drone's propellers or wings:", "o": ["Disrupts airflow and reduces lift, so it must be removed before flight", "Has no effect", "Improves lift"], "k": "Disrupts airflow and reduces lift, so it must be removed before flight", "e": "Even a thin layer of frost can significantly reduce lift and increase drag.", "img": null, "area": "wx"}, {"id": 2204, "c": "Weather", "a": "UA.III.B.K1", "q": "Structural icing requires:", "o": ["Visible moisture and temperatures at or below freezing", "Dry air", "High pressure"], "k": "Visible moisture and temperatures at or below freezing", "e": "Ice forms when supercooled water droplets hit the aircraft.", "img": null, "area": "wx"}, {"id": 2205, "c": "Weather", "a": "UA.III.B.K1", "q": "Mechanical turbulence near the ground is caused by:", "o": ["Wind flowing over buildings, trees, and terrain", "The sun", "Cold fronts only"], "k": "Wind flowing over buildings, trees, and terrain", "e": "Obstacles break up smooth airflow, creating eddies.", "img": null, "area": "wx"}, {"id": 2206, "c": "Weather", "a": "UA.III.B.K1", "q": "When flying on the downwind side of a large building, expect:", "o": ["Turbulence and possible downdrafts", "Calm air", "Strong updrafts only"], "k": "Turbulence and possible downdrafts", "e": "Air spills over and swirls behind buildings.", "img": null, "area": "wx"}, {"id": 2207, "c": "Weather", "a": "UA.III.B.K1", "q": "Wind on the downwind (lee) side of a mountain ridge can produce:", "o": ["Strong downdrafts and turbulence", "Smooth air", "No wind"], "k": "Strong downdrafts and turbulence", "e": "Air flowing over the ridge sinks and tumbles on the lee side.", "img": null, "area": "wx"}, {"id": 2208, "c": "Weather", "a": "UA.III.B.K1", "q": "Convective turbulence is most common:", "o": ["On sunny afternoons when the ground heats unevenly", "At night", "Over snow"], "k": "On sunny afternoons when the ground heats unevenly", "e": "Rising thermals create bumpy air, especially over different surfaces.", "img": null, "area": "wx"}, {"id": 2209, "c": "Weather", "a": "UA.III.B.K1", "q": "A temperature inversion is:", "o": ["An increase in temperature with altitude", "A decrease in temperature with altitude", "A pressure drop"], "k": "An increase in temperature with altitude", "e": "In an inversion, warm air sits above cool air near the surface.", "img": null, "area": "wx"}, {"id": 2210, "c": "Weather", "a": "UA.III.B.K1", "q": "A ground-based temperature inversion often leads to:", "o": ["Smooth air but poor visibility from haze, smoke, or fog", "Severe thunderstorms", "Strong gusty winds"], "k": "Smooth air but poor visibility from haze, smoke, or fog", "e": "Pollutants and moisture get trapped below the inversion.", "img": null, "area": "wx"}, {"id": 2211, "c": "Weather", "a": "UA.III.B.K1", "q": "Wind shear is:", "o": ["A sudden change in wind speed or direction over a short distance", "Steady wind", "Wind from behind"], "k": "A sudden change in wind speed or direction over a short distance", "e": "Wind shear can occur at any altitude and is dangerous near the ground.", "img": null, "area": "wx"}, {"id": 2212, "c": "Weather", "a": "UA.III.B.K1", "q": "Low-level wind shear is often found:", "o": ["Near thunderstorms, fronts, and temperature inversions", "Only at high altitude", "Only over the ocean"], "k": "Near thunderstorms, fronts, and temperature inversions", "e": "These are common sources of wind shear close to the surface.", "img": null, "area": "wx"}, {"id": 2213, "c": "Weather", "a": "UA.III.B.K1", "q": "Sea breezes blow:", "o": ["From the water toward land during the day", "From land toward water during the day", "Only at night"], "k": "From the water toward land during the day", "e": "Land heats faster in the day, so cooler air moves in from the water.", "img": null, "area": "wx"}, {"id": 2214, "c": "Weather", "a": "UA.III.B.K1", "q": "What weather is typical of a moist, unstable air mass?", "o": ["Cumuliform clouds, showery precipitation, and good visibility outside showers", "Stratiform clouds and fog", "Smooth air and steady rain"], "k": "Cumuliform clouds, showery precipitation, and good visibility outside showers", "e": "Unstable air produces vertical clouds and showers.", "img": null, "area": "wx"}, {"id": 2215, "c": "Weather", "a": "UA.III.B.K1", "q": "What weather is typical of a stable air mass?", "o": ["Stratiform clouds, steady precipitation, smooth air, and fair to poor visibility", "Cumulus clouds and gusty winds", "Thunderstorms"], "k": "Stratiform clouds, steady precipitation, smooth air, and fair to poor visibility", "e": "Stable air resists vertical motion.", "img": null, "area": "wx"}, {"id": 2216, "c": "Weather", "a": "UA.III.B.K1", "q": "When moist, warm air is lifted over a mountain, it:", "o": ["Cools and may form clouds", "Warms and dries out", "Stays the same"], "k": "Cools and may form clouds", "e": "Rising air expands and cools.", "img": null, "area": "wx"}, {"id": 2217, "c": "Weather", "a": "UA.III.B.K1", "q": "Gusty winds make drone operations harder because:", "o": ["Sudden changes in airspeed and direction can upset the aircraft and drain the battery", "Gusts improve GPS", "They only affect manned aircraft"], "k": "Sudden changes in airspeed and direction can upset the aircraft and drain the battery", "e": "Gusts increase workload, reduce control margins, and use more power.", "img": null, "area": "wx"}, {"id": 2218, "c": "Weather", "a": "UA.III.B.K1", "q": "Hail can be found:", "o": ["Inside or near thunderstorms, even in clear air below the anvil", "Only in winter", "Only in fog"], "k": "Inside or near thunderstorms, even in clear air below the anvil", "e": "Hail can be thrown miles from the storm.", "img": null, "area": "wx"}, {"id": 2219, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "How does high density altitude affect a drone?", "o": ["Propellers produce less thrust, so performance and flight time decrease", "More lift and longer flights", "No effect on drones"], "k": "Propellers produce less thrust, so performance and flight time decrease", "e": "Thinner air reduces propeller and wing efficiency.", "img": null, "area": "perf"}, {"id": 2220, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Which conditions produce the lowest density altitude (best performance)?", "o": ["Cold, dry air at low elevation with high pressure", "Hot, humid air at high elevation", "Hot, dry air at sea level"], "k": "Cold, dry air at low elevation with high pressure", "e": "Cold, dense air gives the best performance.", "img": null, "area": "perf"}, {"id": 2221, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Why does humid air reduce performance?", "o": ["Water vapor is lighter than dry air, so humid air is less dense", "Humid air is heavier", "It cools the motors"], "k": "Water vapor is lighter than dry air, so humid air is less dense", "e": "Moist air is less dense, raising density altitude.", "img": null, "area": "perf"}, {"id": 2222, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "As altitude increases, air density:", "o": ["Decreases", "Increases", "Stays the same"], "k": "Decreases", "e": "Air gets thinner with height.", "img": null, "area": "perf"}, {"id": 2223, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Pressure altitude is the altitude shown when the altimeter is set to:", "o": ["29.92 inches of mercury", "The local altimeter setting", "Zero"], "k": "29.92 inches of mercury", "e": "Pressure altitude uses the standard datum of 29.92 inHg.", "img": null, "area": "perf"}, {"id": 2224, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Load factor is:", "o": ["The ratio of the load on the wings (or rotors) to the total weight", "The payload weight", "The battery capacity"], "k": "The ratio of the load on the wings (or rotors) to the total weight", "e": "Load factor is measured in Gs.", "img": null, "area": "perf"}, {"id": 2225, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "In a coordinated 45-degree banked level turn, the load factor is about:", "o": ["1.4 Gs", "2 Gs", "1 G"], "k": "1.4 Gs", "e": "45 degrees is about 1.41 Gs; 60 degrees is 2 Gs.", "img": null, "area": "perf"}, {"id": 2226, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "An unmanned airplane weighing 33 pounds makes a 30-degree banked turn (load factor about 1.154). The structure must support about:", "o": ["38 pounds", "33 pounds", "66 pounds"], "k": "38 pounds", "e": "33 x 1.154 is about 38 pounds.", "img": null, "area": "perf"}, {"id": 2227, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "The remote pilot should consider that the load factor on an unmanned airplane increases any time:", "o": ["The airplane is banked in a level turn or pulls up sharply", "It flies straight and level", "It descends at idle"], "k": "The airplane is banked in a level turn or pulls up sharply", "e": "Turns and abrupt maneuvers raise load factor.", "img": null, "area": "perf"}, {"id": 2228, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Stall speed increases when:", "o": ["Load factor increases, such as in a steep turn", "The aircraft flies slower", "The CG moves aft"], "k": "Load factor increases, such as in a steep turn", "e": "Stall speed goes up with the square root of load factor.", "img": null, "area": "perf"}, {"id": 2229, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A stall occurs when:", "o": ["The wing exceeds its critical angle of attack", "Airspeed is too high", "The engine stops"], "k": "The wing exceeds its critical angle of attack", "e": "A stall can happen at any airspeed or attitude if the critical angle of attack is exceeded.", "img": null, "area": "perf"}, {"id": 2230, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "What are the four forces acting on an aircraft in flight?", "o": ["Lift, weight, thrust, and drag", "Lift, gravity, speed, and wind", "Push, pull, up, and down"], "k": "Lift, weight, thrust, and drag", "e": "These four forces are in balance in steady flight.", "img": null, "area": "perf"}, {"id": 2231, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "In steady, unaccelerated flight:", "o": ["Lift equals weight and thrust equals drag", "Lift is greater than weight", "Thrust is greater than drag"], "k": "Lift equals weight and thrust equals drag", "e": "The forces are balanced in straight-and-level flight.", "img": null, "area": "perf"}, {"id": 2232, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A multirotor drone climbs by:", "o": ["Increasing the speed of all rotors", "Tilting forward", "Slowing all rotors"], "k": "Increasing the speed of all rotors", "e": "More rotor speed means more thrust than weight.", "img": null, "area": "perf"}, {"id": 2233, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A multirotor moves forward by:", "o": ["Speeding up the rear rotors and slowing the front rotors to tilt forward", "Speeding up the front rotors", "Turning off two motors"], "k": "Speeding up the rear rotors and slowing the front rotors to tilt forward", "e": "Tilting the thrust vector moves the drone.", "img": null, "area": "perf"}, {"id": 2234, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A quadcopter turns (yaws) by:", "o": ["Changing the speed of opposite-spinning rotor pairs", "Tilting sideways", "Using a rudder"], "k": "Changing the speed of opposite-spinning rotor pairs", "e": "Unequal torque between clockwise and counterclockwise rotors creates yaw.", "img": null, "area": "perf"}, {"id": 2235, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Why do adjacent rotors on a quadcopter spin in opposite directions?", "o": ["To cancel torque so the drone does not spin", "To go faster", "To save battery"], "k": "To cancel torque so the drone does not spin", "e": "Opposite rotation balances the torque reaction.", "img": null, "area": "perf"}, {"id": 2236, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "To ensure the center of gravity limits are not exceeded, follow:", "o": ["The aircraft manufacturer's weight and balance guidance and loading instructions", "The FAA's general rule of thumb", "The visual observer's suggestion"], "k": "The aircraft manufacturer's weight and balance guidance and loading instructions", "e": "Manufacturers set the CG limits; follow their instructions.", "img": null, "area": "perf"}, {"id": 2237, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A CG that is too far forward on an unmanned airplane causes:", "o": ["A nose-heavy condition that may make the nose hard to raise", "Instability and spins", "Faster cruise"], "k": "A nose-heavy condition that may make the nose hard to raise", "e": "A forward CG reduces elevator authority.", "img": null, "area": "perf"}, {"id": 2238, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A payload mounted off-center on a multirotor will:", "o": ["Shift the CG, increasing motor load on one side and reducing stability", "Have no effect", "Improve flight time"], "k": "Shift the CG, increasing motor load on one side and reducing stability", "e": "An unbalanced load makes some motors work harder.", "img": null, "area": "perf"}, {"id": 2239, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Total weight 10 pounds and total moment 50 pound-inches. Where is the CG?", "o": ["5 inches from the datum", "50 inches from the datum", "0.2 inches from the datum"], "k": "5 inches from the datum", "e": "CG = total moment divided by total weight = 50/10 = 5 inches.", "img": null, "area": "perf"}, {"id": 2240, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A 2-pound camera is mounted 6 inches aft of the datum. What is its moment?", "o": ["12 pound-inches", "3 pound-inches", "8 pound-inches"], "k": "12 pound-inches", "e": "Moment = weight x arm = 2 x 6 = 12.", "img": null, "area": "perf"}, {"id": 2241, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Hot weather affects LiPo batteries by:", "o": ["Shortening their life and increasing the risk of failure if they overheat", "Making them last much longer", "Having no effect"], "k": "Shortening their life and increasing the risk of failure if they overheat", "e": "High heat stresses lithium cells; let them cool before charging.", "img": null, "area": "perf"}, {"id": 2242, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Cold weather affects drone batteries by:", "o": ["Reducing available capacity and voltage, shortening flight time", "Doubling flight time", "Making them charge faster"], "k": "Reducing available capacity and voltage, shortening flight time", "e": "Keep batteries warm before flight in cold weather.", "img": null, "area": "perf"}, {"id": 2243, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "A sudden voltage drop during flight in cold weather can cause:", "o": ["An early low-battery warning or forced landing", "A longer flight", "Stronger GPS"], "k": "An early low-battery warning or forced landing", "e": "Cold cells sag under load.", "img": null, "area": "perf"}, {"id": 2244, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Flying into a strong headwind on the way out means:", "o": ["The return trip will be faster, but plan battery reserves for the whole flight", "You must fly lower", "The battery will last longer"], "k": "The return trip will be faster, but plan battery reserves for the whole flight", "e": "Always plan for wind and keep reserve power.", "img": null, "area": "perf"}, {"id": 2245, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "Hovering at high density altitude requires:", "o": ["More power, so flight time is shorter", "Less power", "The same power as at sea level"], "k": "More power, so flight time is shorter", "e": "Rotors must spin faster in thin air.", "img": null, "area": "perf"}, {"id": 2246, "c": "Loading & Performance", "a": "UA.IV.A.K1", "q": "What happens to drone performance when flying from a low-elevation field in Texas to a mountain site at 8,000 feet on a hot day?", "o": ["Lower thrust, shorter flight time, and less payload capacity", "Better performance", "No change"], "k": "Lower thrust, shorter flight time, and less payload capacity", "e": "High altitude and heat both raise density altitude.", "img": null, "area": "perf"}, {"id": 2247, "c": "Operations", "a": "UA.V.D.K1", "q": "Aeronautical decision-making (ADM) is:", "o": ["A systematic approach to consistently choosing the best course of action in a situation", "Following the manufacturer's checklist only", "Asking the client what to do"], "k": "A systematic approach to consistently choosing the best course of action in a situation", "e": "ADM is the mental process pilots use to make good decisions.", "img": null, "area": "ops"}, {"id": 2248, "c": "Operations", "a": "UA.V.D.K1", "q": "Risk management is the part of ADM that:", "o": ["Identifies hazards, assesses risk, and decides how to reduce it", "Only covers weather", "Lets the client set the rules"], "k": "Identifies hazards, assesses risk, and decides how to reduce it", "e": "Identify, assess, and mitigate are the core steps.", "img": null, "area": "ops"}, {"id": 2249, "c": "Operations", "a": "UA.V.D.K1", "q": "In risk assessment, risk is a combination of:", "o": ["Likelihood and severity", "Speed and altitude", "Cost and time"], "k": "Likelihood and severity", "e": "A risk matrix rates how likely a hazard is and how bad the outcome would be.", "img": null, "area": "ops"}, {"id": 2250, "c": "Operations", "a": "UA.V.D.K1", "q": "The 3P model for risk management stands for:", "o": ["Perceive, Process, Perform", "Plan, Prepare, Proceed", "Pilot, Plane, Pressure"], "k": "Perceive, Process, Perform", "e": "Perceive hazards, process their risk, and perform risk management.", "img": null, "area": "ops"}, {"id": 2251, "c": "Operations", "a": "UA.V.D.K1", "q": "The 5P checklist includes:", "o": ["Plan, Plane, Pilot, Passengers, and Programming", "Pre-flight, Power, Payload, Props, Position", "People, Property, Place, Price, Pay"], "k": "Plan, Plane, Pilot, Passengers, and Programming", "e": "The 5Ps help review risk at key decision points; for drones, Passengers means people involved and nearby.", "img": null, "area": "ops"}, {"id": 2252, "c": "Operations", "a": "UA.V.D.K1", "q": "In the PAVE checklist, the 'E' stands for:", "o": ["External pressures", "Equipment", "Emergencies"], "k": "External pressures", "e": "PAVE: Pilot, Aircraft, enVironment, External pressures.", "img": null, "area": "ops"}, {"id": 2253, "c": "Operations", "a": "UA.V.D.K1", "q": "In the IMSAFE checklist, the 'S' stands for:", "o": ["Stress", "Sleep", "Speed"], "k": "Stress", "e": "IMSAFE: Illness, Medication, Stress, Alcohol, Fatigue, Emotion.", "img": null, "area": "ops"}, {"id": 2254, "c": "Operations", "a": "UA.V.D.K1", "q": "Which DECIDE step comes right after 'Detect'?", "o": ["Estimate the need to react", "Choose a course of action", "Do the necessary action"], "k": "Estimate the need to react", "e": "DECIDE: Detect, Estimate, Choose, Identify, Do, Evaluate.", "img": null, "area": "ops"}, {"id": 2255, "c": "Operations", "a": "UA.V.D.K1", "q": "The last step of the DECIDE model is:", "o": ["Evaluate the effect of the action", "Do the action", "Detect the change"], "k": "Evaluate the effect of the action", "e": "Evaluate checks whether the action worked.", "img": null, "area": "ops"}, {"id": 2256, "c": "Operations", "a": "UA.V.D.K4", "q": "A remote pilot who says 'Rules don't apply to me' shows which hazardous attitude?", "o": ["Anti-authority", "Resignation", "Impulsivity"], "k": "Anti-authority", "e": "The antidote is: follow the rules, they are usually right.", "img": null, "area": "ops"}, {"id": 2257, "c": "Operations", "a": "UA.V.D.K4", "q": "A remote pilot who says 'What's the use?' shows which hazardous attitude?", "o": ["Resignation", "Macho", "Invulnerability"], "k": "Resignation", "e": "The antidote is: I'm not helpless, I can make a difference.", "img": null, "area": "ops"}, {"id": 2258, "c": "Operations", "a": "UA.V.D.K4", "q": "A remote pilot who says 'Do something, quickly!' shows which hazardous attitude?", "o": ["Impulsivity", "Anti-authority", "Resignation"], "k": "Impulsivity", "e": "The antidote is: not so fast, think first.", "img": null, "area": "ops"}, {"id": 2259, "c": "Operations", "a": "UA.V.D.K4", "q": "A news station pilot takes risks to impress others and get the shot. This is:", "o": ["Macho", "Resignation", "Anti-authority"], "k": "Macho", "e": "Taking chances to prove yourself is the macho attitude.", "img": null, "area": "ops"}, {"id": 2260, "c": "Operations", "a": "UA.V.D.K4", "q": "A remote pilot is pressured to fly in marginal weather because a client is paying. The best action is:", "o": ["Postpone the flight until conditions are safe", "Fly lower to stay under the clouds", "Fly quickly to finish before it gets worse"], "k": "Postpone the flight until conditions are safe", "e": "External pressure is a major hazard; safety comes first.", "img": null, "area": "ops"}, {"id": 2261, "c": "Operations", "a": "UA.V.D.K2", "q": "Crew resource management (CRM) for small UAS means:", "o": ["Using all available resources, including crew, equipment, and information, through good communication", "Letting the VO make all decisions", "Flying without a crew"], "k": "Using all available resources, including crew, equipment, and information, through good communication", "e": "CRM covers teamwork, workload, and communication.", "img": null, "area": "ops"}, {"id": 2262, "c": "Operations", "a": "UA.V.D.K2", "q": "When adapting CRM to sUAS operations, all crewmembers should:", "o": ["Be included in pre-flight planning and briefings and speak up about hazards", "Stay quiet unless asked", "Only listen to the client"], "k": "Be included in pre-flight planning and briefings and speak up about hazards", "e": "Good CRM empowers every crewmember.", "img": null, "area": "ops"}, {"id": 2263, "c": "Operations", "a": "UA.V.D.K3", "q": "Situational awareness means:", "o": ["Knowing what is happening around you and what will happen next", "Only watching the drone's screen", "Knowing the client's schedule"], "k": "Knowing what is happening around you and what will happen next", "e": "It includes aircraft state, airspace, weather, people, and hazards.", "img": null, "area": "ops"}, {"id": 2264, "c": "Operations", "a": "UA.V.D.K3", "q": "Which can reduce a remote pilot's situational awareness?", "o": ["Fatigue, distractions, and task saturation", "Proper rest", "A clear briefing"], "k": "Fatigue, distractions, and task saturation", "e": "Workload and distractions are common causes of lost awareness.", "img": null, "area": "ops"}, {"id": 2265, "c": "Operations", "a": "UA.V.D.K3", "q": "Task saturation happens when:", "o": ["A pilot has more tasks than they can handle safely", "The drone has too much battery", "The VO is talking"], "k": "A pilot has more tasks than they can handle safely", "e": "Prioritize tasks or reduce workload when overloaded.", "img": null, "area": "ops"}, {"id": 2266, "c": "Operations", "a": "UA.V.D.K3", "q": "Complacency is a hazard because:", "o": ["Routine flights can lead pilots to skip checks and miss warning signs", "It makes pilots too careful", "It only affects new pilots"], "k": "Routine flights can lead pilots to skip checks and miss warning signs", "e": "Experienced pilots are often more vulnerable to complacency.", "img": null, "area": "ops"}, {"id": 2267, "c": "Operations", "a": "UA.V.E.K1", "q": "Hypoxia is:", "o": ["A lack of enough oxygen in the body", "Too much oxygen", "A type of fatigue"], "k": "A lack of enough oxygen in the body", "e": "Remote pilots rarely face altitude hypoxia, but it can occur in high mountains.", "img": null, "area": "ops"}, {"id": 2268, "c": "Operations", "a": "UA.V.E.K2", "q": "Which is true regarding alcohol in the body?", "o": ["Small amounts can impair judgment, and only time removes it", "Coffee speeds up how fast it leaves the body", "A cold shower removes alcohol"], "k": "Small amounts can impair judgment, and only time removes it", "e": "The body breaks down alcohol at a fixed rate; nothing speeds it up.", "img": null, "area": "ops"}, {"id": 2269, "c": "Operations", "a": "UA.V.E.K2", "q": "Before flying while taking an over-the-counter medication, a remote pilot should:", "o": ["Check the label for side effects like drowsiness, and not fly if impaired", "Fly as normal", "Double the dose"], "k": "Check the label for side effects like drowsiness, and not fly if impaired", "e": "Many common drugs, like antihistamines, can impair performance.", "img": null, "area": "ops"}, {"id": 2270, "c": "Operations", "a": "UA.V.E.K3", "q": "Dehydration can cause:", "o": ["Headache, fatigue, and reduced judgment", "Better focus", "Faster reactions"], "k": "Headache, fatigue, and reduced judgment", "e": "Drink water, especially on hot field days.", "img": null, "area": "ops"}, {"id": 2271, "c": "Operations", "a": "UA.V.E.K3", "q": "Heatstroke is:", "o": ["A failure of the body's ability to control its temperature", "A mild sunburn", "A type of hypoxia"], "k": "A failure of the body's ability to control its temperature", "e": "Heat illness is a real danger on long summer flight days.", "img": null, "area": "ops"}, {"id": 2272, "c": "Operations", "a": "UA.V.E.K4", "q": "Fatigue affects remote pilots by:", "o": ["Slowing reaction time and impairing judgment", "Improving focus", "Having no effect if you drink coffee"], "k": "Slowing reaction time and impairing judgment", "e": "Rest is the only real cure for fatigue.", "img": null, "area": "ops"}, {"id": 2273, "c": "Operations", "a": "UA.V.E.K5", "q": "Stress that comes from a sudden emergency is:", "o": ["Acute stress", "Chronic stress", "Normal stress"], "k": "Acute stress", "e": "Acute stress is short-term; chronic stress builds over time.", "img": null, "area": "ops"}, {"id": 2274, "c": "Operations", "a": "UA.V.E.K6", "q": "At night, the eye's rods are:", "o": ["Better for night vision and peripheral vision", "Used only for color", "Useless"], "k": "Better for night vision and peripheral vision", "e": "Cones see color in daylight; rods work in low light.", "img": null, "area": "ops"}, {"id": 2275, "c": "Operations", "a": "UA.V.E.K6", "q": "It takes about how long for the eyes to fully adapt to darkness?", "o": ["30 minutes", "2 minutes", "5 hours"], "k": "30 minutes", "e": "Full dark adaptation takes about 30 minutes; bright light ruins it.", "img": null, "area": "ops"}, {"id": 2276, "c": "Operations", "a": "UA.V.E.K6", "q": "At night, the best way to see a faint object is to:", "o": ["Look slightly to the side of it (off-center viewing)", "Stare directly at it", "Close one eye"], "k": "Look slightly to the side of it (off-center viewing)", "e": "Rods are concentrated away from the center of the eye.", "img": null, "area": "ops"}, {"id": 2277, "c": "Operations", "a": "UA.V.E.K8", "q": "At night, a light that stays fixed in one place against a dark background may seem to move. This illusion is called:", "o": ["Autokinesis", "Flicker vertigo", "Spatial disorientation"], "k": "Autokinesis", "e": "Staring at a single light at night can make it appear to move.", "img": null, "area": "ops"}, {"id": 2278, "c": "Operations", "a": "UA.V.E.K8", "q": "To reduce night illusions while flying at night, a remote pilot should:", "o": ["Keep the eyes moving, scan, and avoid staring at the aircraft's lights", "Stare at the drone's light", "Fly farther away"], "k": "Keep the eyes moving, scan, and avoid staring at the aircraft's lights", "e": "Moving your eyes helps prevent autokinesis.", "img": null, "area": "ops"}, {"id": 2279, "c": "Operations", "a": "UA.V.E.K8", "q": "Before a night flight, the pilot should:", "o": ["Survey the area in daylight to find obstacles like wires and towers", "Fly first and check after", "Skip the preflight"], "k": "Survey the area in daylight to find obstacles like wires and towers", "e": "Obstacles are hard to see at night; scout the site in daylight.", "img": null, "area": "ops"}, {"id": 2280, "c": "Operations", "a": "UA.V.E.K8", "q": "A red flashlight is useful at night because it:", "o": ["Helps preserve night vision", "Is brighter", "Charges the drone"], "k": "Helps preserve night vision", "e": "Dim red light has less effect on dark adaptation.", "img": null, "area": "ops"}, {"id": 2281, "c": "Operations", "a": "UA.V.C.K1", "q": "Who is responsible for briefing participants on emergency procedures before a commercial flight?", "o": ["The remote PIC", "The client", "The visual observer"], "k": "The remote PIC", "e": "Section 107.49 makes the remote PIC responsible for the crew briefing.", "img": null, "area": "ops"}, {"id": 2282, "c": "Operations", "a": "UA.V.C.K1", "q": "If the control link is lost, the drone will normally:", "o": ["Follow its programmed lost-link procedure, such as return-to-home or hover", "Fly away", "Land immediately in every case"], "k": "Follow its programmed lost-link procedure, such as return-to-home or hover", "e": "Know and set the lost-link behavior before flight.", "img": null, "area": "ops"}, {"id": 2283, "c": "Operations", "a": "UA.V.C.K1", "q": "Before using return-to-home (RTH), the remote PIC should make sure:", "o": ["The RTH altitude clears all obstacles along the return path", "RTH is turned off", "The home point is set after takeoff"], "k": "The RTH altitude clears all obstacles along the return path", "e": "A low RTH altitude can fly the drone into trees or buildings.", "img": null, "area": "ops"}, {"id": 2284, "c": "Operations", "a": "UA.V.C.K1", "q": "During a fly-away, the remote PIC should:", "o": ["Follow the emergency plan, notify ATC if near controlled airspace or an airport, and track the drone", "Do nothing", "Turn off the controller and leave"], "k": "Follow the emergency plan, notify ATC if near controlled airspace or an airport, and track the drone", "e": "Have a plan and notify the appropriate parties.", "img": null, "area": "ops"}, {"id": 2285, "c": "Operations", "a": "UA.V.C.K1", "q": "If a drone loses GPS and drifts, the remote PIC should:", "o": ["Switch to manual (attitude) control and fly it back carefully", "Climb as high as possible", "Let it drift"], "k": "Switch to manual (attitude) control and fly it back carefully", "e": "Without GPS the drone may not hold position; the pilot must fly it manually.", "img": null, "area": "ops"}, {"id": 2286, "c": "Operations", "a": "UA.V.C.K1", "q": "A LiPo battery catches fire during flight operations. What is the best response?", "o": ["Keep clear and let it burn out or smother it with a large amount of water or sand, per local guidance", "Pick it up and throw it", "Blow on it"], "k": "Keep clear and let it burn out or smother it with a large amount of water or sand, per local guidance", "e": "Lithium fires are hard to put out; avoid touching or breathing the smoke.", "img": null, "area": "ops"}, {"id": 2287, "c": "Operations", "a": "UA.V.C.K1", "q": "To avoid a possible collision with a manned airplane, you climb your drone 150 feet from 400 to 550 feet AGL. You should:", "o": ["Report the deviation to the FAA if requested", "Do nothing, it was an emergency", "Keep flying at 550 feet"], "k": "Report the deviation to the FAA if requested", "e": "In an emergency you may deviate, but the FAA may request a report.", "img": null, "area": "ops"}, {"id": 2288, "c": "Operations", "a": "UA.V.B.K1", "q": "A preflight 'site survey' helps identify:", "o": ["Obstacles, people, airspace, terrain, and possible emergency landing areas", "Only the takeoff spot", "The battery voltage"], "k": "Obstacles, people, airspace, terrain, and possible emergency landing areas", "e": "Survey the area to spot hazards before the flight.", "img": null, "area": "ops"}, {"id": 2289, "c": "Operations", "a": "UA.V.B.K1", "q": "Electromagnetic interference near power lines or radio towers can cause:", "o": ["Compass errors and control link problems", "Better GPS reception", "Longer flight time"], "k": "Compass errors and control link problems", "e": "Large metal structures and high voltage can confuse the compass.", "img": null, "area": "ops"}, {"id": 2290, "c": "Operations", "a": "UA.V.B.K1", "q": "Flying near steel structures like bridges may cause:", "o": ["Compass interference and loss of GPS signal", "Improved stability", "No problems"], "k": "Compass interference and loss of GPS signal", "e": "Steel and concrete can block GPS and affect the magnetometer.", "img": null, "area": "ops"}, {"id": 2291, "c": "Operations", "a": "UA.V.B.K1", "q": "Radio frequency interference can come from:", "o": ["Other radios, Wi-Fi, cell towers, and power lines", "Sunshine only", "Only other drones"], "k": "Other radios, Wi-Fi, cell towers, and power lines", "e": "Many sources share the 2.4 and 5.8 GHz bands.", "img": null, "area": "ops"}, {"id": 2292, "c": "Operations", "a": "UA.V.B.K1", "q": "Before flying a multirotor, the takeoff area should be:", "o": ["Level, clear of people and obstacles, and away from loose debris", "Next to spectators", "Under trees"], "k": "Level, clear of people and obstacles, and away from loose debris", "e": "Propwash can kick up debris; keep people clear.", "img": null, "area": "ops"}, {"id": 2293, "c": "Operations", "a": "UA.V.B.K2", "q": "A visual observer and remote PIC should agree on:", "o": ["Standard phrases and hand signals before flight", "Nothing; just talk as needed", "Only the landing time"], "k": "Standard phrases and hand signals before flight", "e": "Clear, practiced communication prevents misunderstanding.", "img": null, "area": "ops"}, {"id": 2294, "c": "Operations", "a": "UA.V.B.K2", "q": "If the visual observer loses sight of the drone, the best action is to:", "o": ["Tell the remote PIC right away", "Look for it quietly", "Leave the area"], "k": "Tell the remote PIC right away", "e": "The crew must keep the drone in sight and communicate.", "img": null, "area": "ops"}, {"id": 2295, "c": "Operations", "a": "UA.V.C.K1", "q": "The scan for traffic should be done by:", "o": ["Looking in short sections of about 10 degrees, pausing about 1 second in each", "Sweeping the sky continuously", "Looking only straight ahead"], "k": "Looking in short sections of about 10 degrees, pausing about 1 second in each", "e": "The eye needs to stop to detect objects.", "img": null, "area": "ops"}, {"id": 2296, "c": "Operations", "a": "UA.V.C.K1", "q": "An aircraft that appears to have no relative motion (stays in one spot) while getting bigger is:", "o": ["On a collision course", "Moving away", "Not a threat"], "k": "On a collision course", "e": "A target that does not move across your view but grows is headed toward you.", "img": null, "area": "ops"}, {"id": 2297, "c": "Operations", "a": "UA.V.C.K1", "q": "Most midair collisions happen:", "o": ["Near airports in good weather during the day", "At night in bad weather", "Over the ocean"], "k": "Near airports in good weather during the day", "e": "Clear days near airports have the most traffic.", "img": null, "area": "ops"}, {"id": 2298, "c": "Operations", "a": "UA.V.C.K1", "q": "Which part of the sky is hardest to scan for aircraft?", "o": ["Areas blocked by the sun's glare", "Directly overhead", "Over open water"], "k": "Areas blocked by the sun's glare", "e": "Sun glare hides traffic; use sunglasses and shading.", "img": null, "area": "ops"}, {"id": 2299, "c": "Operations", "a": "UA.V.B.K1", "q": "A drone's maximum radio range in the manual is measured:", "o": ["In ideal conditions without interference", "In every condition", "With trees in the way"], "k": "In ideal conditions without interference", "e": "Real-world range is often much shorter.", "img": null, "area": "ops"}, {"id": 2300, "c": "Operations", "a": "UA.V.B.K1", "q": "Why is it important to update the drone's firmware and maps?", "o": ["To get bug fixes, safety features, and current no-fly databases", "Only for new paint colors", "It is never important"], "k": "To get bug fixes, safety features, and current no-fly databases", "e": "Updates can change flight behavior, so test before critical work.", "img": null, "area": "ops"}, {"id": 2301, "c": "Maintenance", "a": "UA.V.F.K1", "q": "Under what condition should a small UA operator establish scheduled maintenance?", "o": ["When the manufacturer does not provide a maintenance schedule", "Only after an accident", "Never"], "k": "When the manufacturer does not provide a maintenance schedule", "e": "If no manufacturer guidance exists, the operator should create a schedule based on use and experience.", "img": null, "area": "ops"}, {"id": 2302, "c": "Maintenance", "a": "UA.V.F.K1", "q": "Scheduled maintenance for a small UAS should follow:", "o": ["The manufacturer's recommendations, or a schedule based on flight hours or cycles", "The FAA's monthly schedule", "Nothing in particular"], "k": "The manufacturer's recommendations, or a schedule based on flight hours or cycles", "e": "Use manufacturer guidance whenever it exists.", "img": null, "area": "ops"}, {"id": 2303, "c": "Maintenance", "a": "UA.V.F.K2", "q": "According to Part 107, the responsibility to inspect the small UAS to ensure it is safe rests with the:", "o": ["Remote pilot in command", "Owner", "Manufacturer"], "k": "Remote pilot in command", "e": "Section 107.49 requires the remote PIC to inspect before each flight.", "img": null, "area": "ops"}, {"id": 2304, "c": "Maintenance", "a": "UA.V.F.K1", "q": "Unscheduled maintenance is:", "o": ["Repairs needed because of damage, wear, or a failure found during inspection", "Maintenance done on a calendar", "Optional cleaning"], "k": "Repairs needed because of damage, wear, or a failure found during inspection", "e": "Fix problems found in preflight before flying.", "img": null, "area": "ops"}, {"id": 2305, "c": "Maintenance", "a": "UA.V.F.K1", "q": "Who can perform maintenance on a small UAS under Part 107?", "o": ["Anyone, but the remote PIC must make sure it is safe before flight", "Only an FAA-certificated mechanic", "Only the manufacturer"], "k": "Anyone, but the remote PIC must make sure it is safe before flight", "e": "Part 107 does not require certificated mechanics, but the aircraft must be safe.", "img": null, "area": "ops"}, {"id": 2306, "c": "Maintenance", "a": "UA.V.F.K3", "q": "Keeping maintenance records is helpful because it:", "o": ["Tracks component life, repairs, and recurring problems", "Is required by Part 107", "Replaces the preflight inspection"], "k": "Tracks component life, repairs, and recurring problems", "e": "Records are recommended, not required, by Part 107.", "img": null, "area": "ops"}, {"id": 2307, "c": "Maintenance", "a": "UA.V.F.K2", "q": "During preflight, motors should be checked for:", "o": ["Debris, loose mounts, smooth rotation, and unusual sounds", "Paint color", "Their brand name"], "k": "Debris, loose mounts, smooth rotation, and unusual sounds", "e": "Damaged motors can fail in flight.", "img": null, "area": "ops"}, {"id": 2308, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Propellers should be inspected for:", "o": ["Nicks, cracks, bends, and secure attachment", "Their color", "Only the logo"], "k": "Nicks, cracks, bends, and secure attachment", "e": "Damaged props can break and cause a crash.", "img": null, "area": "ops"}, {"id": 2309, "c": "Maintenance", "a": "UA.V.F.K2", "q": "A drone was dropped and now vibrates in flight. The remote PIC should:", "o": ["Ground it and inspect the props, motors, and frame before flying again", "Fly it to see if it gets better", "Fly only at low altitude"], "k": "Ground it and inspect the props, motors, and frame before flying again", "e": "Vibration is a warning sign of damage.", "img": null, "area": "ops"}, {"id": 2310, "c": "Maintenance", "a": "UA.V.F.K2", "q": "LiPo batteries should be charged:", "o": ["With the correct charger, on a fireproof surface, and never left unattended", "Overnight on a bed", "With any charger"], "k": "With the correct charger, on a fireproof surface, and never left unattended", "e": "Most battery fires happen during charging.", "img": null, "area": "ops"}, {"id": 2311, "c": "Maintenance", "a": "UA.V.F.K2", "q": "A LiPo battery that has been punctured should be:", "o": ["Treated as a fire hazard and disposed of properly", "Charged to test it", "Taped up and used"], "k": "Treated as a fire hazard and disposed of properly", "e": "Damaged lithium batteries can ignite.", "img": null, "area": "ops"}, {"id": 2312, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Why should batteries be stored at a partial (storage) charge?", "o": ["It extends battery life and lowers fire risk", "It makes them heavier", "It is required by law"], "k": "It extends battery life and lowers fire risk", "e": "Storage around 3.8 volts per cell is ideal for LiPos.", "img": null, "area": "ops"}, {"id": 2313, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Lithium batteries transported by air must follow:", "o": ["Hazardous materials rules (for example, PHMSA and airline limits)", "No rules", "Only the drone manufacturer's rules"], "k": "Hazardous materials rules (for example, PHMSA and airline limits)", "e": "Spare lithium batteries usually must be in carry-on luggage with terminals protected.", "img": null, "area": "ops"}, {"id": 2314, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Before each flight, the remote PIC should confirm the controller and drone:", "o": ["Have enough battery charge and a solid control link", "Are the same color", "Were bought together"], "k": "Have enough battery charge and a solid control link", "e": "Check both batteries and the link.", "img": null, "area": "ops"}, {"id": 2315, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Loose screws or cracked arms found during preflight mean:", "o": ["Repair before flight; the aircraft is not in a condition for safe operation", "Fly carefully", "Fly only at night"], "k": "Repair before flight; the aircraft is not in a condition for safe operation", "e": "Section 107.15 prohibits operating unless the aircraft is in safe condition.", "img": null, "area": "ops"}, {"id": 2316, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Why should the drone's compass be recalibrated after traveling a long distance?", "o": ["Magnetic variation and local fields change with location", "The battery needs it", "It is never needed"], "k": "Magnetic variation and local fields change with location", "e": "The magnetometer needs calibration for the local magnetic field.", "img": null, "area": "ops"}, {"id": 2317, "c": "Maintenance", "a": "UA.V.F.K2", "q": "Which is a sign of a failing LiPo battery?", "o": ["Swelling (puffing), heat, or a cell that will not balance", "A clean label", "Normal weight"], "k": "Swelling (puffing), heat, or a cell that will not balance", "e": "Puffed batteries must be retired.", "img": null, "area": "ops"}];
